import React, { useState } from "react";
import type { OptimizationStrategy } from "../utils/itineraryPlanner";
import { api, createItinerary, errorMessage, displayNumber } from "../api";

import { Cpu, ArrowLeft, Play, Database, Download, Copy, Check } from "lucide-react";
import { useTheme } from "../context/ThemeContext";

interface ResearchViewProps {
  onBack: () => void;
}

interface RunRow {
  cityId: string;
  days: number;
  budget: number;
  strategy: OptimizationStrategy;
  attractions: number;
  cost: number;
  distance: number;
  dijkstraCalls: number;
  runtimeMs: number;
}

export const ResearchView: React.FC<ResearchViewProps> = ({ onBack }) => {
  const [results, setResults] = useState<RunRow[]>([]);
  const [isRunning, setIsRunning] = useState<boolean>(false);
  const [copied, setCopied] = useState<boolean>(false);

  const [requestError, setRequestError] = useState("");
  const runSimulationMatrix = async () => {
    setIsRunning(true);
    setResults([]); setRequestError("");
    try {
      const runs: RunRow[] = [];
      const testCities = (await api.catalog()).filter(d => d.hotels.length).slice(0,2).map(d => ({id:d.id,hotelId:d.hotels[0].id}));

      // 1. Duration Experiment
      for (const city of testCities) {
        for (const days of [1, 2, 3]) {
          const {result:res} = await createItinerary({
            cityId: city.id,
            tripDays: days,
            budget: 10000,
            startingHotelId: city.hotelId,
            startTime: "08:00 AM",
            strategy: "distance-first"
          }, "distance-first");
          runs.push({
            cityId: city.id,
            days,
            budget: 10000,
            strategy: "distance-first",
            attractions: res.attractionCount,
            cost: res.totalCost,
            distance: res.totalDistanceKm,
            dijkstraCalls: res.stats.dijkstraFallbackCalls,
            runtimeMs: res.stats.executionTimeMs
          });
        }
      }

      // 2. Budget Experiment
      for (const city of testCities) {
        for (const budget of [500, 900, 1200, 1500, 3000]) {
          const {result:res} = await createItinerary({
            cityId: city.id,
            tripDays: 1,
            budget,
            startingHotelId: city.hotelId,
            startTime: "08:00 AM",
            strategy: "distance-first"
          }, "distance-first");
          runs.push({
            cityId: city.id,
            days: 1,
            budget,
            strategy: "distance-first",
            attractions: res.attractionCount,
            cost: res.totalCost,
            distance: res.totalDistanceKm,
            dijkstraCalls: res.stats.dijkstraFallbackCalls,
            runtimeMs: res.stats.executionTimeMs
          });
        }
      }

      // 3. Strategy Experiment
      const strategies: OptimizationStrategy[] = ["budget-first", "rating-first", "distance-first"];
      for (const city of testCities) {
        for (const strategy of strategies) {
          const {result:res} = await createItinerary({
            cityId: city.id,
            tripDays: 2,
            budget: 10000,
            startingHotelId: city.hotelId,
            startTime: "08:00 AM",
            strategy
          }, strategy);
          runs.push({
            cityId: city.id,
            days: 2,
            budget: 10000,
            strategy,
            attractions: res.attractionCount,
            cost: res.totalCost,
            distance: res.totalDistanceKm,
            dijkstraCalls: res.stats.dijkstraFallbackCalls,
            runtimeMs: res.stats.executionTimeMs
          });
        }
      }

      setResults(runs);
    } catch(error) { setResults([]); setRequestError(errorMessage(error)); }
    finally { setIsRunning(false); }
  };

  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(JSON.stringify(results, null, 2));
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (error) {
      console.error("Failed to copy research results:", error);
      window.alert("Unable to copy the results. Check clipboard permission and try again.");
    }
  };

  if(requestError) return <p role="alert">{requestError} <button onClick={runSimulationMatrix}>Retry</button></p>;
  return (
    <div className="max-w-7xl mx-auto p-4 sm:p-6 md:p-8 space-y-8 animate-fadeIn text-charcoal">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-stone/30 pb-4">
        <div className="flex items-center gap-3">
          <button
            onClick={onBack}
            className="p-2 border border-stone/30 hover:bg-stone/10 transition-colors cursor-pointer"
            aria-label="Back to main app"
          >
            <ArrowLeft className="w-5 h-5 text-stone" />
          </button>
          <div>
            <div className="flex items-center gap-1.5 font-mono text-xs text-gold uppercase tracking-widest font-bold">
              <Cpu className="w-4 h-4 text-gold" />
              <span>Academic Validation Suite</span>
            </div>
            <h1 className="font-display text-3xl font-bold text-ink mt-1">Research Simulation Console</h1>
          </div>
        </div>

        <button
          onClick={runSimulationMatrix}
          disabled={isRunning}
          className="flex items-center gap-2 px-5 py-2.5 bg-ink text-salt hover:bg-gold hover:text-ink font-mono text-sm border-2 border-gold transition-colors font-bold disabled:opacity-50 cursor-pointer"
        >
          <Play className="w-4 h-4 fill-current" />
          {isRunning ? "Executing..." : "Run Simulation Matrix"}
        </button>
      </div>

      {/* Intro Banner */}
      <div className="bg-salt border border-stone/30 p-4 font-mono text-xs leading-relaxed max-w-4xl">
        <p className="font-bold mb-2 text-ink">🔬 STUDY DESCRIPTION & METHODOLOGY</p>
        <p className="text-stone">
          This Console evaluates the server-side <strong>Stepwell Routing Engine</strong>. 
          By executing multiple itineraries programmatically across various limits (Duration, Budget, and Optimization Strategy), we validate that heuristic constraint handling, Dijkstra graph nodes relaxation, and edge weight calculations behave predictably on limited data spaces ($V \le 10$).
        </p>
      </div>

      {results.length > 0 && (
        <div className="space-y-6">
          {/* Action Bar */}
          <div className="flex justify-end gap-2.5">
            <button
              onClick={copyToClipboard}
              className="flex items-center gap-1.5 px-3 py-1.5 border border-stone/30 hover:bg-stone/10 font-mono text-xs cursor-pointer transition-colors"
            >
              {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5 text-stone" />}
              <span>{copied ? "Copied JSON!" : "Copy JSON"}</span>
            </button>
          </div>

          {/* Results Tables */}
          <div className="bg-white border border-stone/30 shadow-sm overflow-x-auto">
            <table className="w-full text-left font-mono text-xs border-collapse">
              <thead>
                <tr className="bg-ink text-salt border-b border-gold">
                  <th className="p-3 font-mono font-bold uppercase">City</th>
                  <th className="p-3 font-mono font-bold uppercase text-center">Days</th>
                  <th className="p-3 font-mono font-bold uppercase text-right">Budget Limit</th>
                  <th className="p-3 font-mono font-bold uppercase">Strategy</th>
                  <th className="p-3 font-mono font-bold uppercase text-center">Attractions</th>
                  <th className="p-3 font-mono font-bold uppercase text-right">Total Cost</th>
                  <th className="p-3 font-mono font-bold uppercase text-right">Distance</th>
                  <th className="p-3 font-mono font-bold uppercase text-center">Dijkstra Fallbacks</th>
                  <th className="p-3 font-mono font-bold uppercase text-right">Runtime</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-stone/20">
                {results.map((row, idx) => (
                  <tr key={idx} className="hover:bg-salt/40 transition-colors">
                    <td className="p-3 font-bold text-ink">{row.cityId.toUpperCase()}</td>
                    <td className="p-3 text-center">{row.days}</td>
                    <td className="p-3 text-right">₹{row.budget.toLocaleString("en-IN")}</td>
                    <td className="p-3">
                      <span className={`px-2 py-0.5 border text-[10px] uppercase font-bold ${
                        row.strategy === "budget-first" ? "bg-emerald-50 border-emerald-300 text-emerald-800" :
                        row.strategy === "rating-first" ? "bg-amber-50 border-amber-300 text-amber-800" :
                        "bg-sky-50 border-sky-300 text-sky-800"
                      }`}>
                        {row.strategy.replace("-first", "")}
                      </span>
                    </td>
                    <td className="p-3 text-center font-bold">{row.attractions} / 4</td>
                    <td className="p-3 text-right text-emerald-700 font-bold">₹{row.cost.toLocaleString("en-IN")}</td>
                    <td className="p-3 text-right">{row.distance} km</td>
                    <td className="p-3 text-center">{row.dijkstraCalls}</td>
                    <td className="p-3 text-right text-stone">{displayNumber(row.runtimeMs)} ms</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

frontend/src/components/PwaInstallPrompt:
import React, { useState } from "react";
import { Smartphone, Download, X, Sparkles, Check } from "lucide-react";

interface PwaInstallPromptProps {
  deferredPrompt: any;
  onDismiss: () => void;
  onInstalled: () => void;
}

export const PwaInstallPrompt: React.FC<PwaInstallPromptProps> = ({
  deferredPrompt,
  onDismiss,
  onInstalled,
}) => {
  const [isInstalling, setIsInstalling] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const handleInstallClick = async () => {
    if (!deferredPrompt) {
      // Fallback instructions if native prompt isn't supported or directly available
      alert(
        'To install, tap your browser menu (⋮ or Share icon) and select "Add to Home Screen".',
      );
      onDismiss();
      return;
    }

    setIsInstalling(true);
    try {
      deferredPrompt.prompt();
      const choiceResult = await deferredPrompt.userChoice;
      if (choiceResult.outcome === "accepted") {
        setIsSuccess(true);
        setTimeout(() => {
          onInstalled();
        }, 1500);
      } else {
        onDismiss();
      }
    } catch (err) {
      console.warn("Error during PWA installation prompt:", err);
      onDismiss();
    } finally {
      setIsInstalling(false);
    }
  };

  return (
    <div
      role="dialog"
      aria-label="Add Heritage Tourism Planner to Home Screen"
      className="fixed bottom-4 right-4 z-50 max-w-md w-[calc(100vw-2rem)] bg-ink text-salt border-2 border-gold p-4 shadow-2xl space-y-3 font-mono text-xs animate-fadeIn"
    >
      <div className="flex items-start justify-between gap-2 border-b border-stone/40 pb-2">
        <div className="flex items-center gap-2">
          <div className="bg-gold text-ink p-1.5 font-bold border border-ink shrink-0">
            <Smartphone className="w-4 h-4 text-ink" />
          </div>
          <div>
            <span className="text-gold font-bold text-[10px] uppercase tracking-wider block">
              Offline App Available
            </span>
            <h4 className="font-display text-sm text-salt font-bold">
              Add to Home Screen
            </h4>
          </div>
        </div>

        <button
          onClick={onDismiss}
          aria-label="Dismiss installation prompt"
          className="text-stone hover:text-salt p-1 transition-colors cursor-pointer"
        >
          <X className="w-4 h-4" />
        </button>
      </div>

      <p className="text-stone font-body text-xs leading-relaxed">
        Install the app shell for offline access. Loading saved itineraries and
        budgets requires a connection to the server.
      </p>

      {isSuccess ? (
        <div className="p-2.5 bg-gold text-ink font-bold flex items-center justify-center gap-2 border border-ink">
          <Check className="w-4 h-4 text-ink" />
          <span>App Installed to Home Screen!</span>
        </div>
      ) : (
        <div className="flex items-center justify-end gap-2 pt-1">
          <button
            onClick={onDismiss}
            className="px-3 py-1.5 border border-stone/50 hover:bg-stone/20 text-stone hover:text-salt font-bold transition-colors cursor-pointer"
          >
            Maybe Later
          </button>

          <button
            onClick={handleInstallClick}
            disabled={isInstalling}
            className="px-4 py-1.5 bg-gold hover:bg-gold/90 text-ink font-bold border border-ink shadow-xs flex items-center gap-1.5 transition-colors cursor-pointer"
          >
            <Download className="w-3.5 h-3.5 text-ink" />
            <span>{isInstalling ? "Installing..." : "Add to Home Screen"}</span>
          </button>
        </div>
      )}
    </div>
  );
};

frontend/src/components/ProfileDashboard:
import React, { useState, useEffect } from "react";
import { api, useApi, loadItinerary } from "../api";
import { ItineraryConfig } from "./ItineraryView";
import { useLanguage } from "../context/LanguageContext";
import {
  User,
  Mail,
  Lock,
  Calendar,
  DollarSign,
  ChevronRight,
  ArrowRight,
  Building2,
  CheckCircle2,
  AlertCircle,
  SlidersHorizontal,
  LogOut,
  Sparkles,
  MapPin,
  ShieldCheck,
  Check,
  Edit3,
  ExternalLink,
  Plus,
} from "lucide-react";

export interface SavedTrip {
  id: string;
  title: string;
  dates: string;
  daysCount: number;
  totalCost: number;
  planningProgress: number;
  statusLabel: string;
  sitesCount: number;
  sitesList: string[];
  config: ItineraryConfig;
}

interface ProfileDashboardViewProps {
  currentUser: {
    name: string;
    email: string;
    role: "tourist" | "operator";
  } | null;
  onOpenItinerary: (config: ItineraryConfig) => void;
  onOpenExplore: () => void;
  onOpenPlanner: () => void;
  onOpenAdminDashboard?: (hotelId?: string, create?: boolean) => void;
  onLogout: () => void;
}

export const ProfileDashboardView: React.FC<ProfileDashboardViewProps> = ({
  currentUser,
  onOpenItinerary,
  onOpenExplore,
  onOpenPlanner,
  onOpenAdminDashboard,
  onLogout,
}) => {
  const { t } = useLanguage();
  const [role, setRole] = useState<"tourist" | "operator">(
    currentUser?.role || "tourist",
  );

  const [name, setName] = useState<string>(
    currentUser?.name || "Heritage Traveler",
  );
  const [email, setEmail] = useState<string>(
    currentUser?.email || "traveler@heritage.in",
  );

  useEffect(() => {
    if (currentUser) {
      setName(currentUser.name);
      setEmail(currentUser.email);
      setRole(currentUser.role);
    }
  }, [currentUser]);
  const [currentPassword, setCurrentPassword] = useState<string>("");
  const [newPassword, setNewPassword] = useState<string>("");
  const [saveSuccessNotice, setSaveSuccessNotice] = useState<string | null>(
    null,
  );

  const request = useApi(async () => {
    const hidden: string[] = JSON.parse(sessionStorage.getItem("heritage_api_hidden_trip_ids") || "[]");
    const ids = (await api.savedTrips()).map(row => row.id).filter(id => !hidden.includes(id));
    const trips = await Promise.all(ids.map(id => loadItinerary(id)));
    const listings = currentUser?.role === "operator" ? await api.adminList("hotels") : [];
    return {trips:trips.map(({config,result,dto}) => ({id:config.tripId,title:result.activeCity.name,
      dates:dto.trip.created_at,daysCount:config.tripDays,totalCost:result.totalCost,planningProgress:dto.trip.generated_at?100:0,
      statusLabel:dto.trip.generation_summary?.status ?? "Not generated",sitesCount:result.attractionCount,
      sitesList:result.dayPlans.flatMap(d=>d.stops.filter(s=>s.type==="attraction").map(s=>s.name)),config})),
      listings:listings.map(h=>({id:h.id,name:h.name,type:h.stay_type,destination:h.destination_id,
        status:h.provenance_status,lastUpdated:"Not available",price:`₹${h.price_per_night} / night`}))};
  }, [currentUser?.email,currentUser?.role]);
  const savedTrips = request.data?.trips ?? [];
  const operatorListings = request.data?.listings ?? [];
  const handleOpenTrip = (trip: SavedTrip) => onOpenItinerary(trip.config);
  const handleSettingsSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setSaveSuccessNotice(
      "Account editing is not available from the API yet. No changes were saved.",
    );
    setTimeout(() => {
      setSaveSuccessNotice(null);
    }, 4000);
  };

  const handleDeleteTrip = (tripId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const ids: string[] = JSON.parse(sessionStorage.getItem("heritage_api_trip_ids") || "[]");
    sessionStorage.setItem("heritage_api_trip_ids", JSON.stringify(ids.filter(id => id !== tripId)));
    const hidden: string[] = JSON.parse(sessionStorage.getItem("heritage_api_hidden_trip_ids") || "[]");
    sessionStorage.setItem("heritage_api_hidden_trip_ids", JSON.stringify([...new Set([...hidden,tripId])]));
    request.reload();
  };

  if(request.loading) return <p role="status">Loading account records...</p>;
  if(request.error) return <p role="alert">{request.error} <button onClick={request.reload}>Retry</button></p>;
  return (
    <div className="bg-salt min-h-screen py-8 px-4 sm:px-6 lg:px-8 border-b border-stone/30 animate-fadeIn selection:bg-gold selection:text-ink">
      <div className="max-w-5xl mx-auto space-y-10">
        {/* HEADER */}
        <div className="bg-ink text-salt p-6 sm:p-8 border-2 border-gold space-y-4 shadow-lg relative overflow-hidden rounded-2xl">
          <div className="absolute top-0 right-0 w-64 h-64 bg-stepwell-pattern opacity-10 pointer-events-none" />

          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-stone/30 pb-4">
            <div className="space-y-1">
              <div className="flex items-center gap-2">
                <span className="bg-gold text-ink font-mono text-[11px] uppercase font-bold px-2.5 py-0.5 tracking-wider border border-ink rounded-md">
                  {role === "operator"
                    ? "Registered Tour Operator"
                    : "Heritage Tourist"}
                </span>
                <span className="font-mono text-[10px] text-stone">
                  • Signed-in Account
                </span>
              </div>

              <h1 className="font-display text-2xl sm:text-4xl text-salt font-bold">
                Welcome back, {name || "Traveler"}
              </h1>
            </div>

            <div className="flex flex-wrap items-center gap-2 font-mono text-xs">
              <button
                onClick={() =>
                  setSaveSuccessNotice("Your role is supplied by the authenticated server account.")
                }
                className="bg-salt/10 hover:bg-salt/20 text-gold border border-gold/40 px-3 py-1.5 transition-colors cursor-pointer text-[11px] flex items-center gap-1.5 rounded-lg"
                title="Account role from the authentication server"
              >
                <SlidersHorizontal className="w-3.5 h-3.5 text-gold" />
                <span>
                  View Mode: {role === "tourist" ? "Tourist" : "Operator"}
                </span>
              </button>

              {currentUser && onOpenAdminDashboard && (
                <button
                  onClick={() => onOpenAdminDashboard?.()}
                  className="bg-gold text-ink hover:bg-gold/90 border border-gold font-bold px-3 py-1.5 transition-colors cursor-pointer text-[11px] flex items-center gap-1.5 rounded-lg"
                >
                  <ShieldCheck className="w-3.5 h-3.5 text-ink" />
                  <span>Admin Panel</span>
                </button>
              )}

              <button
                onClick={onLogout}
                className="bg-madder hover:bg-madder/90 text-salt border border-madder px-3 py-1.5 transition-colors cursor-pointer text-[11px] flex items-center gap-1.5 rounded-lg"
              >
                <LogOut className="w-3.5 h-3.5 text-salt" />
                <span>Log Out</span>
              </button>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-6 font-mono text-xs text-stone">
            <span className="flex items-center gap-1.5">
              <Mail className="w-4 h-4 text-gold" />
              <span>{email}</span>
            </span>
            <span>•</span>
            <span>Saved Routes: {savedTrips.length}</span>
            <span>•</span>
            <span>Account ID: {currentUser?.email}</span>
          </div>
        </div>

        {saveSuccessNotice && (
          <div className="p-3.5 bg-emerald-900 text-salt border-2 border-emerald-400 text-xs font-mono flex items-center gap-2 shadow-md animate-fadeIn rounded-xl">
            <Check className="w-4 h-4 text-emerald-300" />
            <span className="font-bold">{saveSuccessNotice}</span>
          </div>
        )}

        {/* ROLE BASED MAIN VIEW */}
        {role === "tourist" ? (
          <div className="space-y-6">
            <div className="border-b-2 border-gold pb-3 flex flex-col sm:flex-row sm:items-center justify-between gap-2">
              <div>
                <span className="font-mono text-xs text-gold uppercase tracking-widest block">
                  Itinerary Vault
                </span>
                <h2 className="font-display text-xl sm:text-2xl text-charcoal font-bold">
                  My Saved Heritage Trips
                </h2>
              </div>

              <button
                onClick={onOpenPlanner}
                className="inline-flex items-center gap-2 bg-madder hover:bg-madder/90 text-salt text-xs font-mono font-bold px-4 py-2 border border-madder shadow-xs transition-colors cursor-pointer shrink-0 rounded-lg"
              >
                <Plus className="w-4 h-4 text-salt" />
                <span>Create New Heritage Route</span>
              </button>
            </div>

            {savedTrips.length === 0 ? (
              <div className="bg-white border-2 border-dashed border-stone/40 p-8 text-center space-y-4 rounded-2xl">
                <p className="font-mono text-xs text-stone">
                  No saved trips in your heritage ledger.
                </p>
                <button
                  onClick={onOpenPlanner}
                  className="bg-gold text-ink font-mono text-xs font-bold px-4 py-2 border border-ink cursor-pointer rounded-lg shadow-xs"
                >
                  Build Your First Trip
                </button>
              </div>
            ) : (
              <div className="grid grid-cols-1 gap-4">
                {savedTrips.map((trip) => (
                  <div
                    key={trip.id}
                    className="bg-white border-2 border-stone/40 hover:border-gold p-6 transition-all shadow-2xs space-y-4 group rounded-2xl"
                  >
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-stone/20 pb-3">
                      <div>
                        <div className="flex items-center gap-2">
                          <span className="bg-ink text-gold font-mono text-[10px] font-bold px-2 py-0.5 uppercase rounded-md">
                            {trip.dates}
                          </span>
                          <span className="font-mono text-xs text-stone">
                            {trip.daysCount} Days • {trip.sitesCount}{" "}
                            Destinations
                          </span>
                        </div>
                        <h3 className="font-display text-xl text-charcoal font-bold mt-1 group-hover:text-ink transition-colors">
                          {trip.title}
                        </h3>
                      </div>

                      <div className="text-right shrink-0 font-mono">
                        <span className="text-[10px] text-stone uppercase block">
                          Est. Total Outlay
                        </span>
                        <span className="text-lg font-bold text-ink">
                          ₹{trip.totalCost.toLocaleString()}
                        </span>
                      </div>
                    </div>

                    <div className="flex flex-wrap items-center justify-between gap-4 font-mono text-xs">
                      <div className="space-y-1 max-w-lg">
                        <span className="text-stone text-[10px] uppercase block">
                          Circuit Destinations:
                        </span>
                        <div className="flex flex-wrap items-center gap-1.5">
                          {trip.sitesList.map((site, i) => (
                            <span
                              key={i}
                              className="bg-salt border border-stone/30 text-charcoal px-2 py-0.5 text-[11px] rounded-md"
                            >
                              {site}
                            </span>
                          ))}
                        </div>
                      </div>

                      <div className="flex items-center gap-2 w-full sm:w-auto justify-end pt-2 sm:pt-0">
                        <button
                          onClick={() => handleOpenTrip(trip)}
                          className="bg-ink hover:bg-ink/90 text-salt border border-gold px-4 py-2 text-xs font-bold cursor-pointer transition-colors flex items-center gap-1.5 shadow-xs rounded-lg"
                        >
                          <span>Open Itinerary</span>
                          <ChevronRight className="w-3.5 h-3.5 text-gold" />
                        </button>

                        <button
                          onClick={(e) => handleDeleteTrip(trip.id, e)}
                          className="bg-salt hover:bg-madder/10 text-stone hover:text-madder border border-stone/30 px-3 py-2 text-xs transition-colors cursor-pointer rounded-lg"
                        >
                          Remove
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        ) : (
          /* TOUR OPERATOR DASHBOARD VIEW */
          <div className="space-y-6">
            <div className="border-b-2 border-gold pb-3 flex flex-col sm:flex-row sm:items-center justify-between gap-2">
              <div>
                <span className="font-mono text-xs text-gold uppercase tracking-widest block">
                  Tour Operator Console
                </span>
                <h2 className="font-display text-xl sm:text-2xl text-charcoal font-bold">
                  My Registered Heritage Properties & Stays
                </h2>
              </div>

              <button
                onClick={() => onOpenAdminDashboard?.(undefined, true)}
                className="inline-flex items-center gap-2 bg-madder hover:bg-madder/90 text-salt text-xs font-mono font-bold px-4 py-2 border border-madder shadow-xs transition-colors cursor-pointer shrink-0 rounded-lg"
              >
                <Plus className="w-4 h-4 text-salt" />
                <span>Submit New Property for Audit</span>
              </button>
            </div>

            <div className="grid grid-cols-1 gap-4">
              {operatorListings.map((item) => (
                <div
                  key={item.id}
                  className="bg-white border-2 border-stone/40 p-5 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 font-mono text-xs rounded-2xl shadow-xs"
                >
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <Building2 className="w-4 h-4 text-gold shrink-0" />
                      <span className="font-bold text-charcoal text-sm">
                        {item.name}
                      </span>
                      <span className="bg-salt text-charcoal border border-stone/40 text-[10px] px-2 py-0.5 uppercase rounded-md">
                        {item.type}
                      </span>
                    </div>
                    <p className="text-stone text-[11px]">
                      Destination: {item.destination} • Status:{" "}
                      <strong className="text-emerald-800">
                        {item.status}
                      </strong>
                    </p>
                  </div>

                  <div className="flex items-center gap-3 shrink-0 self-end sm:self-auto">
                    <span className="font-bold text-ink text-sm">
                      {item.price}
                    </span>
                    <button
                      onClick={() => onOpenAdminDashboard?.(item.id)}
                      className="bg-salt hover:bg-stone/20 text-charcoal border border-stone/40 px-3 py-1.5 cursor-pointer flex items-center gap-1 rounded-lg"
                    >
                      <Edit3 className="w-3.5 h-3.5 text-ink" />
                      <span>Edit</span>
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ACCOUNT SETTINGS FORM */}
        <div className="bg-white border-2 border-stone/40 p-6 sm:p-8 space-y-6 shadow-2xs rounded-2xl">
          <div className="border-b border-stone/30 pb-3">
            <span className="font-mono text-xs text-gold uppercase tracking-widest block">
              Security & Credentials
            </span>
            <h2 className="font-display text-xl text-charcoal font-bold">
              Account Preferences
            </h2>
          </div>

          <form
            onSubmit={handleSettingsSubmit}
            className="space-y-5 max-w-2xl font-mono text-xs"
          >
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="block text-charcoal uppercase tracking-wider text-[11px] font-bold">
                  Full Name / Title
                </label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full p-2.5 bg-salt border border-stone/40 text-charcoal text-sm outline-none focus:border-gold rounded-lg"
                  required
                />
              </div>

              <div className="space-y-1.5">
                <label className="block text-charcoal uppercase tracking-wider text-[11px] font-bold">
                  Email Address
                </label>
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full p-2.5 bg-salt border border-stone/40 text-charcoal text-sm outline-none focus:border-gold rounded-lg"
                  required
                />
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2">
              <div className="space-y-1.5">
                <label className="block text-charcoal uppercase tracking-wider text-[11px] font-bold">
                  Current Password
                </label>
                <input
                  type="password"
                  placeholder="••••••••••••"
                  value={currentPassword}
                  onChange={(e) => setCurrentPassword(e.target.value)}
                  className="w-full p-2.5 bg-salt border border-stone/40 text-charcoal text-sm outline-none focus:border-gold rounded-lg"
                />
              </div>

              <div className="space-y-1.5">
                <label className="block text-charcoal uppercase tracking-wider text-[11px] font-bold">
                  New Password
                </label>
                <input
                  type="password"
                  placeholder="Enter new password"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  className="w-full p-2.5 bg-salt border border-stone/40 text-charcoal text-sm outline-none focus:border-gold rounded-lg"
                />
              </div>
            </div>

            <div className="pt-2">
              <button
                type="submit"
                className="bg-ink hover:bg-ink/90 text-salt border border-gold text-xs font-mono font-bold px-6 py-2.5 transition-colors cursor-pointer shadow-xs rounded-lg"
              >
                Save Account Changes
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

frontend/src/components/PlannerModal.tsx:
import React, { useState, useEffect, useRef } from "react";
import type { Destination } from "../api/types";
import { api, useCatalog, EMPTY_DESTINATION, errorMessage, configFromTrip } from "../api";
import { ImageWithFallback } from "./ImageWithFallback";
import {
  X,
  Calendar,
  Check,
  ArrowRight,
  ArrowLeft,
  Plus,
  Minus,
  Hotel,
  Clock,
  Compass,
  SlidersHorizontal,
  Accessibility,
} from "lucide-react";
import { useLanguage } from "../context/LanguageContext";
import { StrategyComparisonModal } from "./StrategyComparisonModal";
import type {
  OptimizationStrategy,
  PlannerConfigPayload,
} from "../utils/itineraryPlanner";

export type { PlannerConfigPayload };

interface PlannerModalProps {
  isOpen: boolean;
  onClose: () => void;
  preselectedDestination?: Destination | null;
  initialConfig?: Partial<PlannerConfigPayload> | null;
  tripList?: Destination[];
  preferredHotels?: Record<string, string>;
  onSelectPreferredHotel?: (cityId: string, hotelId: string) => void;
  onGenerateItinerary: (config: PlannerConfigPayload) => void;
}

export const PlannerModal: React.FC<PlannerModalProps> = ({
  isOpen,
  onClose,
  preselectedDestination,
  initialConfig,
  preferredHotels,
  onSelectPreferredHotel,
  onGenerateItinerary,
}) => {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const { language, t, getName } = useLanguage();

  // Step 1: Selected single city ID
  const [selectedCityId, setSelectedCityId] = useState<string>(() => {
    return preselectedDestination?.id || "";
  });

  // Step 2: Logistics state
  const [tripDays, setTripDays] = useState<number>(2);
  const [budget, setBudget] = useState<number>(8500);
  const [startingHotelId, setStartingHotelId] = useState<string>("");
  const [startTime, setStartTime] = useState<string>("08:00 AM");
  const [wheelchairOnly, setWheelchairOnly] = useState<boolean>(false);

  // Step 3: Comparison Modal trigger state
  const [showComparisonModal, setShowComparisonModal] =
    useState<boolean>(false);

  const catalog = useCatalog(isOpen);
  const destinations = catalog.data ?? [];
  const getCityById = (id: string) => destinations.find(d => d.id === id);
  const activeCity = getCityById(selectedCityId) || destinations[0] || EMPTY_DESTINATION;
  const [pending, setPending] = useState(false);
  const pendingRef = useRef(false);
  const [requestError, setRequestError] = useState("");
  const [createdTrip, setCreatedTrip] = useState<{key:string;id:string} | null>(null);

  // Sync selectedCityId and default starting hotel when modal opens
  useEffect(() => {
    if (isOpen && catalog.data?.length) {
      setStep(1);
      const initialCityId =
        initialConfig?.cityId || preselectedDestination?.id || selectedCityId || destinations[0].id;
      setSelectedCityId(initialCityId);
      const cityObj = getCityById(initialCityId) || destinations[0];
      const preferredForCity = initialConfig?.startingHotelId || preferredHotels?.[initialCityId];
      if (preferredForCity && cityObj.hotels && cityObj.hotels.some(h => h.id === preferredForCity)) {
        setStartingHotelId(preferredForCity);
      } else {
        setStartingHotelId(cityObj.hotels[0]?.id ?? "");
      }

      if (initialConfig?.tripDays) setTripDays(initialConfig.tripDays);
      if (initialConfig?.budget) setBudget(initialConfig.budget);
      if (initialConfig?.startTime) setStartTime(initialConfig.startTime);
      if (initialConfig?.wheelchairAccessibleOnly !== undefined) {
        setWheelchairOnly(initialConfig.wheelchairAccessibleOnly);
      }
    }
  }, [isOpen, preselectedDestination, initialConfig, catalog.data]);

  // When city changes, load preferred stay or fallback to first hotel
  const handleCityChange = (cityId: string) => {
    setSelectedCityId(cityId);
    const cityObj = getCityById(cityId);
    const preferredForCity = preferredHotels?.[cityId];
    if (preferredForCity && cityObj?.hotels.some(h => h.id === preferredForCity)) {
      setStartingHotelId(preferredForCity);
    } else if (cityObj && cityObj.hotels.length > 0) {
      setStartingHotelId(cityObj.hotels[0].id);
    } else { setStartingHotelId(""); }
  };

  const handleStartingHotelChange = (hotelId: string) => {
    setStartingHotelId(hotelId);
    if (onSelectPreferredHotel) {
      onSelectPreferredHotel(selectedCityId, hotelId);
    }
  };

  // Keyboard Escape listener
  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        onClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const handleGenerate = async () => {
    if(pendingRef.current) return;
    pendingRef.current = true; setPending(true); setRequestError("");
    const config: PlannerConfigPayload = {cityId:activeCity.id,tripDays,budget,startingHotelId,
      startTime,wheelchairAccessibleOnly:wheelchairOnly};
    try {
      const key=JSON.stringify(config);
      let id=createdTrip?.key===key ? createdTrip.id : undefined;
      if(!id) { const result=await api.createTrip(config); id=result.trip.id; setCreatedTrip({key,id}); }
      const generated=await api.generate(id);
      onGenerateItinerary(configFromTrip(generated.trip));
      onClose();
    } catch(error) { setRequestError(errorMessage(error)); }
    finally { pendingRef.current = false; setPending(false); }
  };

  if(catalog.loading) return <p role="status">Loading planner destinations... <button onClick={onClose}>Close</button></p>;
  if(catalog.error) return <p role="alert">{catalog.error} <button onClick={catalog.reload}>Retry</button> <button onClick={onClose}>Close</button></p>;
  if(!activeCity.id) return <p role="status">No destinations available. <button onClick={onClose}>Close</button></p>;
  const startingHotelObj =
    activeCity.hotels.find((h) => h.id === startingHotelId) ||
    activeCity.hotels[0];

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="planner-modal-title"
      className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-ink/85 backdrop-blur-xs overflow-y-auto"
      onClick={onClose}
    >
      <div
        className="bg-salt border-2 border-gold max-w-3xl w-full text-charcoal p-5 sm:p-8 relative shadow-2xl my-6 animate-fadeIn rounded-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        {pending && <p role="status">Saving and generating your itinerary...</p>}
        {requestError && <p role="alert">{requestError}</p>}
        {/* Header Bar */}
        <div className="flex items-start justify-between border-b border-stone/30 pb-4 mb-6">
          <div>
            <div className="flex items-center gap-2 font-mono text-xs text-gold uppercase tracking-widest mb-1">
              <Calendar className="w-4 h-4 text-gold" />
              <span>Stepwell Single-City Day Planner</span>
            </div>
            <h2 id="planner-modal-title" className="font-display text-2xl sm:text-3xl text-ink font-semibold">
              {language === "hi"
                ? `${getName(activeCity)} यात्रा योजना`
                : `Plan Your ${getName(activeCity)} Experience`}
            </h2>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 text-stone hover:text-ink hover:bg-stone/20 border border-stone/30 transition-colors cursor-pointer rounded-lg"
            aria-label="Close trip planner"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* ================= STEP INDICATOR: ASCENDING STEPWELL TERRACES ================= */}

        {/* Desktop & Tablet: Ascending Stepwell Terraced Block Motif */}
        <div
          className="hidden sm:grid grid-cols-3 gap-2 mb-8 items-end"
          role="tablist"
          aria-label="Planner Steps"
        >
          {/* STEP 1 BLOCK */}
          <button
            type="button"
            role="tab"
            aria-selected={step === 1}
            aria-current={step === 1 ? "step" : undefined}
            onClick={() => setStep(1)}
            className={`p-3 border text-left w-full transition-all cursor-pointer relative focus:outline-none focus:ring-2 focus:ring-gold rounded-lg ${
              step === 1
                ? "bg-ink text-salt border-2 border-gold font-bold shadow-md"
                : step > 1
                  ? "bg-gold text-ink border border-gold font-bold"
                  : "bg-stone/20 text-stone border border-stone/30 font-medium"
            }`}
          >
            <div className="flex items-center justify-between text-xs font-mono uppercase tracking-wider">
              <span>
                01.{" "}
                {language === "hi"
                  ? "शहर चयन"
                  : "Confirm City"}
              </span>
              {step > 1 ? (
                <div className="w-4 h-4 rounded-full bg-ink text-gold flex items-center justify-center">
                  <Check className="w-3 h-3" />
                </div>
              ) : (
                <span className="text-[10px] opacity-80">Terrace 1</span>
              )}
            </div>
            <div className="font-display text-sm mt-1 truncate">
              {getName(activeCity)}
            </div>
          </button>

          {/* STEP 2 BLOCK */}
          <button
            type="button"
            role="tab"
            aria-selected={step === 2}
            aria-current={step === 2 ? "step" : undefined}
            onClick={() => setStep(2)}
            className={`p-3.5 border text-left w-full transition-all cursor-pointer relative translate-y-[-2px] focus:outline-none focus:ring-2 focus:ring-gold rounded-lg ${
              step === 2
                ? "bg-ink text-salt border-2 border-gold font-bold shadow-md"
                : step > 2
                  ? "bg-gold text-ink border border-gold font-bold"
                  : "bg-stone/20 text-stone border border-stone/30 font-medium"
            }`}
          >
            <div className="flex items-center justify-between text-xs font-mono uppercase tracking-wider">
              <span>
                02.{" "}
                {language === "hi"
                  ? "लॉजिस्टिक्स"
                  : "Logistics"}
              </span>
              {step > 2 ? (
                <div className="w-4 h-4 rounded-full bg-ink text-gold flex items-center justify-center">
                  <Check className="w-3 h-3" />
                </div>
              ) : (
                <span className="text-[10px] opacity-80">Terrace 2</span>
              )}
            </div>
            <div className="font-display text-sm mt-1 truncate">
              {language === "hi"
                ? "होटल और समय"
                : "Hotel & Schedule"}
            </div>
          </button>

          {/* STEP 3 BLOCK */}
          <button
            type="button"
            role="tab"
            aria-selected={step === 3}
            aria-current={step === 3 ? "step" : undefined}
            onClick={() => setStep(3)}
            className={`p-4 border text-left w-full transition-all cursor-pointer relative translate-y-[-4px] focus:outline-none focus:ring-2 focus:ring-gold rounded-lg ${
              step === 3
                ? "bg-ink text-salt border-2 border-gold font-bold shadow-md"
                : "bg-stone/20 text-stone border border-stone/30 font-medium"
            }`}
          >
            <div className="flex items-center justify-between text-xs font-mono uppercase tracking-wider">
              <span>
                03.{" "}
                {language === "hi"
                  ? "समीक्षा"
                  : "Review"}
              </span>
              <span className="text-[10px] opacity-80">Terrace 3</span>
            </div>
            <div className="font-display text-sm mt-1 truncate">
              {language === "hi"
                ? "रूट जनरेट करें"
                : "Generate Itinerary"}
            </div>
          </button>
        </div>

        {/* Mobile Compact Step Indicator */}
        <div className="sm:hidden mb-6 p-2.5 bg-ink text-salt border border-stone/40 font-mono text-xs flex items-center justify-between rounded-lg">
          <div className="flex items-center gap-2">
            <span className="bg-gold text-ink font-bold px-2 py-0.5 text-[10px] rounded">
              STEP {step} OF 3
            </span>
            <span className="font-display text-sm font-semibold">
              {step === 1
                ? "Confirm City"
                : step === 2
                  ? "Hotel & Schedule"
                  : "Review Plan"}
            </span>
          </div>
          <div className="flex gap-1">
            <span
              className={`w-2 h-2 rounded-full ${step >= 1 ? "bg-gold" : "bg-stone"}`}
            />
            <span
              className={`w-2 h-2 rounded-full ${step >= 2 ? "bg-gold" : "bg-stone"}`}
            />
            <span
              className={`w-2 h-2 rounded-full ${step >= 3 ? "bg-gold" : "bg-stone"}`}
            />
          </div>
        </div>

        {/* ================= STEP CONTENT AREA ================= */}
        <div aria-live="polite">
          {/* STEP 1: CONFIRM CITY */}
          {step === 1 && (
            <div className="space-y-5 animate-fadeIn">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-stone/20 pb-3">
                <div>
                  <h3 className="font-display text-xl text-ink font-bold">
                    {language === "hi"
                      ? "लक्ष्य हेरिटेज शहर चुनें"
                      : "Select Target Heritage City"}
                  </h3>
                  <p className="text-xs text-stone font-body">
                    {language === "hi"
                      ? "एक शहर चुनें ताकि दैनिक यात्रा योजना तैयार की जा सके।"
                      : "Pick one city for a dedicated intra-city day-by-day circular itinerary."}
                  </p>
                </div>
              </div>

              {/* City Selector Grid */}
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-4">
                {destinations.map((c) => {
                  const isSelected = c.id === selectedCityId;
                  return (
                    <button
                      key={c.id}
                      onClick={() => handleCityChange(c.id)}
                      aria-pressed={isSelected}
                      className={`p-2 border text-left cursor-pointer transition-all focus:outline-none focus:ring-2 focus:ring-gold rounded-lg ${
                        isSelected
                          ? "bg-ink text-salt border-2 border-gold font-bold shadow-sm"
                          : "bg-salt hover:bg-stone/20 text-charcoal border-stone/30"
                      }`}
                    >
                      <div className="font-display text-xs truncate">
                        {getName(c)}
                      </div>
                      <div
                        className={`text-[10px] font-mono ${isSelected ? "text-gold" : "text-stone"}`}
                      >
                        {c.district}
                      </div>
                    </button>
                  );
                })}
              </div>

              {/* Selected City Highlight Monograph */}
              <div className="bg-ink text-salt border-2 border-gold p-4 sm:p-5 flex flex-col sm:flex-row gap-4 items-center rounded-xl">
                <ImageWithFallback
                  src={activeCity.imageUrl}
                  alt={activeCity.imageAlt || getName(activeCity)}
                  category={activeCity.officialCategory || activeCity.category}
                  className="w-full sm:w-40 h-28 object-cover border border-gold shrink-0 rounded-lg"
                />
                <div className="space-y-2 text-left w-full">
                  <div className="flex items-center justify-between">
                    <span className="font-mono text-[10px] uppercase text-gold tracking-widest">
                      {activeCity.officialCategory}
                    </span>
                    <span className="font-mono text-xs bg-gold text-ink font-bold px-2 py-0.5 rounded">
                      {activeCity.rating}
                    </span>
                  </div>
                  <h4 className="font-display text-xl font-bold text-salt">
                    {getName(activeCity)}
                  </h4>
                  <p className="font-mono text-xs text-stone line-clamp-2">
                    {activeCity.description}
                  </p>
                  <div className="flex items-center gap-4 text-xs font-mono text-gold pt-1 border-t border-stone/30">
                    <span>
                      {activeCity.attractions.length}{" "}
                      {language === "hi"
                        ? "आकर्षण"
                        : "Attractions"}
                    </span>
                    <span>
                      {activeCity.hotels.length}{" "}
                      {language === "hi"
                        ? "होटल"
                        : "Hotel Options"}
                    </span>
                    <span>
                      {activeCity.restaurants.length}{" "}
                      {language === "hi"
                        ? "रेस्तरां"
                        : "Restaurants"}
                    </span>
                  </div>
                </div>
              </div>

              {/* Next Step Control */}
              <div className="pt-4 border-t border-stone/30 flex justify-end">
                <button
                  onClick={() => setStep(2)}
                  className="bg-gold hover:bg-ink hover:text-gold text-ink border border-gold font-mono text-xs font-bold px-6 py-3 uppercase tracking-wider flex items-center gap-2 transition-colors cursor-pointer shadow-md focus:outline-none focus:ring-2 focus:ring-gold rounded-lg"
                >
                  <span>
                    {language === "hi"
                      ? "लॉजिस्टिक्स की ओर बढ़ें"
                      : "Continue to Logistics"}
                  </span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* STEP 2: LOGISTICS */}
          {step === 2 && (
            <div className="space-y-6 animate-fadeIn">
              <div>
                <h3 className="font-display text-xl text-ink font-bold border-b border-stone/20 pb-2">
                  {language === "hi"
                    ? `${getName(activeCity)} के लिए लॉजिस्टिक्स`
                    : `Trip Logistics for ${getName(activeCity)}`}
                </h3>
                <p className="text-xs text-stone font-body mt-1">
                  Configure duration, budget, starting accommodation, and daily
                  morning start time.
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Trip Length Selector */}
                <div className="bg-white border border-stone/40 p-4 space-y-3 rounded-xl">
                  <label
                    htmlFor="planner-trip-days"
                    className="font-mono text-xs font-bold text-charcoal uppercase tracking-wider flex items-center gap-2"
                  >
                    <Calendar className="w-4 h-4 text-gold" />
                    1. {t("planner.days", "Trip Duration")}
                  </label>
                  <div className="flex items-center justify-between border border-stone/30 bg-salt p-2 rounded-lg">
                    <button
                      type="button"
                      onClick={() => setTripDays(Math.max(1, tripDays - 1))}
                      aria-label="Decrease trip duration"
                      className="w-8 h-8 bg-ink text-gold flex items-center justify-center font-bold hover:bg-stone/40 cursor-pointer focus:outline-none focus:ring-2 focus:ring-gold rounded-md"
                    >
                      <Minus className="w-4 h-4" />
                    </button>
                    <div className="text-center">
                      <span
                        id="planner-trip-days"
                        className="font-display text-xl font-bold text-ink"
                      >
                        {tripDays}
                      </span>
                      <span className="font-mono text-xs text-stone block">
                        {language === "hi"
                          ? "दिन"
                          : "Days"}
                      </span>
                    </div>
                    <button
                      type="button"
                      onClick={() => setTripDays(Math.min(7, tripDays + 1))}
                      aria-label="Increase trip duration"
                      className="w-8 h-8 bg-ink text-gold flex items-center justify-center font-bold hover:bg-stone/40 cursor-pointer focus:outline-none focus:ring-2 focus:ring-gold rounded-md"
                    >
                      <Plus className="w-4 h-4" />
                    </button>
                  </div>
                </div>

                {/* Budget Limit Input */}
                <div className="bg-white border border-stone/40 p-4 space-y-3 rounded-xl">
                  <label
                    htmlFor="planner-budget-input"
                    className="font-mono text-xs font-bold text-charcoal uppercase tracking-wider flex items-center justify-between"
                  >
                    <span>2. {t("planner.budget", "Total Budget (₹)")}</span>
                    <span className="text-gold font-bold text-sm">
                      ₹{budget.toLocaleString("en-IN")}
                    </span>
                  </label>
                  <input
                    id="planner-budget-input"
                    type="range"
                    min="3000"
                    max="30000"
                    step="500"
                    value={budget}
                    onChange={(e) => setBudget(Number(e.target.value))}
                    className="w-full accent-gold cursor-pointer focus:outline-none focus:ring-2 focus:ring-gold rounded-lg"
                  />
                  <div className="flex justify-between font-mono text-[10px] text-stone">
                    <span>₹3,000 (Economy)</span>
                    <span>₹30,000 (Luxury)</span>
                  </div>
                </div>

                {/* Starting Hotel Selection */}
                <div className="bg-white border border-stone/40 p-4 space-y-3 rounded-xl">
                  <label
                    htmlFor="planner-starting-hotel"
                    className="font-mono text-xs font-bold text-charcoal uppercase tracking-wider flex items-center gap-2"
                  >
                    <Hotel className="w-4 h-4 text-gold" />
                    3. {t("planner.startingHotel", "Starting Hotel / Stay")}
                  </label>
                  <select
                    id="planner-starting-hotel"
                    value={startingHotelId}
                    onChange={(e) => handleStartingHotelChange(e.target.value)}
                    className="w-full bg-salt text-charcoal font-mono text-xs p-2.5 border border-stone/40 outline-none focus:border-gold focus:ring-1 focus:ring-gold cursor-pointer font-bold rounded-lg"
                  >
                    {activeCity.hotels.map((h) => {
                      const isPref = preferredHotels?.[selectedCityId] === h.id;
                      return (
                        <option key={h.id} value={h.id}>
                          {h.name} ({h.pricePerNight}/night • {h.tier}){" "}
                          {isPref ? "★ (Preferred Stay)" : ""}
                        </option>
                      );
                    })}
                  </select>
                  {startingHotelObj && (
                    <div className="font-mono text-[11px] text-stone space-y-1">
                      <p>
                        {startingHotelObj.location} •{" "}
                        {startingHotelObj.stayType}
                      </p>
                    </div>
                  )}
                </div>

                {/* Morning Start Time */}
                <div className="bg-white border border-stone/40 p-4 space-y-3 rounded-xl">
                  <label
                    htmlFor="planner-start-time"
                    className="font-mono text-xs font-bold text-charcoal uppercase tracking-wider flex items-center gap-2"
                  >
                    <Clock className="w-4 h-4 text-gold" />
                    4. {t("planner.dailyStartTime", "Daily Start Time")}
                  </label>
                  <select
                    id="planner-start-time"
                    value={startTime}
                    onChange={(e) => setStartTime(e.target.value)}
                    className="w-full bg-salt text-charcoal font-mono text-xs p-2.5 border border-stone/40 outline-none focus:border-gold focus:ring-1 focus:ring-gold cursor-pointer font-bold rounded-lg"
                  >
                    <option value="07:00 AM">07:00 AM (Early Departure)</option>
                    <option value="08:00 AM">08:00 AM (Recommended)</option>
                    <option value="09:00 AM">09:00 AM (Standard)</option>
                    <option value="10:00 AM">10:00 AM (Relaxed)</option>
                    <option value="11:00 AM">11:00 AM (Late Start)</option>
                  </select>
                </div>

                {/* 5. Accessibility Constraint Toggle */}
                <div className="bg-emerald-50/50 border border-emerald-300 p-4 space-y-2 col-span-1 md:col-span-2 rounded-xl">
                  <label className="flex items-start sm:items-center justify-between gap-3 cursor-pointer">
                    <div className="space-y-0.5">
                      <span className="font-mono text-xs font-bold text-emerald-950 uppercase tracking-wider flex items-center gap-2">
                        <Accessibility className="w-4 h-4 text-emerald-800" />
                        5. Accessibility Constraint: Wheelchair-Only Route
                      </span>
                      <p className="text-xs text-stone font-body">
                        Filter the Greedy routing algorithm to visit only
                        wheelchair-accessible monuments (ramps, wide plazas,
                        flat ground).
                      </p>
                    </div>
                    <input
                      type="checkbox"
                      checked={wheelchairOnly}
                      onChange={(e) => setWheelchairOnly(e.target.checked)}
                      className="w-5 h-5 accent-emerald-800 shrink-0 cursor-pointer mt-1 sm:mt-0 rounded"
                    />
                  </label>
                </div>
              </div>

              {/* Back / Next Controls */}
              <div className="pt-4 border-t border-stone/30 flex justify-between">
                <button
                  onClick={() => setStep(1)}
                  className="bg-stone/20 hover:bg-stone/30 text-charcoal border border-stone/40 font-mono text-xs font-bold px-4 py-2.5 uppercase tracking-wider flex items-center gap-2 cursor-pointer focus:outline-none focus:ring-2 focus:ring-gold rounded-lg"
                >
                  <ArrowLeft className="w-4 h-4" />
                  <span>
                    {language === "hi"
                      ? "पीछे"
                      : "Back"}
                  </span>
                </button>

                <button
                  onClick={() => setStep(3)}
                  className="bg-gold hover:bg-ink hover:text-gold text-ink border border-gold font-mono text-xs font-bold px-6 py-2.5 uppercase tracking-wider flex items-center gap-2 cursor-pointer shadow-md focus:outline-none focus:ring-2 focus:ring-gold rounded-lg"
                >
                  <span>
                    {language === "hi"
                      ? "योजना समीक्षा करें"
                      : "Review Plan"}
                  </span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* STEP 3: REVIEW & GENERATE */}
          {step === 3 && (
            <div className="space-y-6 animate-fadeIn">
              <div>
                <h3 className="font-display text-xl text-ink font-bold border-b border-stone/20 pb-2">
                  {language === "hi"
                    ? "वृत्ताकार मार्ग सेटिंग्स की समीक्षा करें"
                    : "Review Circular Route Settings"}
                </h3>
              </div>

              {/* Summary Card */}
              <div className="bg-ink text-salt border-2 border-gold p-6 space-y-4 shadow-lg rounded-xl">
                <div className="flex items-center justify-between border-b border-stone/30 pb-3">
                  <div>
                    <span className="font-mono text-[10px] text-gold uppercase tracking-widest block">
                      Target Heritage City
                    </span>
                    <h4 className="font-display text-2xl font-bold text-salt">
                      {getName(activeCity)}
                    </h4>
                  </div>
                  <span className="bg-gold text-ink font-mono text-xs font-bold px-3 py-1 uppercase rounded-md">
                    {tripDays}{" "}
                    {language === "hi"
                      ? "दिन"
                      : "Days"}
                  </span>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 font-mono text-xs">
                  <div className="bg-salt/10 p-3 border border-stone/30 rounded-lg">
                    <span className="text-stone text-[10px] uppercase block">
                      Starting Hotel
                    </span>
                    <span className="font-bold text-gold truncate block">
                      {startingHotelObj?.name}
                    </span>
                  </div>
                  <div className="bg-salt/10 p-3 border border-stone/30 rounded-lg">
                    <span className="text-stone text-[10px] uppercase block">
                      Daily Start Time
                    </span>
                    <span className="font-bold text-gold block">
                      {startTime}
                    </span>
                  </div>
                  <div className="bg-salt/10 p-3 border border-stone/30 rounded-lg">
                    <span className="text-stone text-[10px] uppercase block">
                      Budget Cap
                    </span>
                    <span className="font-bold text-gold block">
                      ₹{budget.toLocaleString("en-IN")}
                    </span>
                  </div>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="pt-4 border-t border-stone/30 flex flex-col sm:flex-row gap-3 justify-between items-stretch sm:items-center">
                <button
                  type="button"
                  onClick={() => setStep(2)}
                  className="bg-stone/20 hover:bg-stone/30 text-charcoal border border-stone/40 font-mono text-xs font-bold px-4 py-2.5 uppercase tracking-wider flex items-center justify-center gap-2 cursor-pointer rounded-lg"
                >
                  <ArrowLeft className="w-4 h-4" />
                  <span>
                    {language === "hi"
                      ? "लॉजिस्टिक्स बदलें"
                      : "Adjust Logistics"}
                  </span>
                </button>

                <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2">
                  <button
                    type="button"
                    onClick={() => setShowComparisonModal(true)}
                    className="bg-salt hover:bg-ink hover:text-salt text-ink border-2 border-gold font-mono text-xs font-bold px-5 py-3 uppercase tracking-wider flex items-center justify-center gap-2 cursor-pointer shadow-md transition-all rounded-lg"
                  >
                    <SlidersHorizontal className="w-4 h-4 text-gold" />
                    <span>Compare optimization strategies</span>
                  </button>

                  <button
                    type="button"
                    onClick={handleGenerate} disabled={pending || !startingHotelId}
                    className="bg-gold hover:bg-ink hover:text-gold text-ink border border-gold font-mono text-xs font-bold px-6 py-3 uppercase tracking-wider flex items-center justify-center gap-2 cursor-pointer shadow-xl transition-all rounded-lg"
                  >
                    <Compass className="w-4 h-4 text-ink hover:text-gold" />
                    <span>
                      {t("planner.generateItinerary", "Generate Circular Plan")}
                    </span>
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Strategy Comparison Modal Overlay */}
      {showComparisonModal && (
        <StrategyComparisonModal
          isOpen={showComparisonModal}
          onClose={() => setShowComparisonModal(false)}
          config={{
            cityId: activeCity.id,
            tripDays,
            budget,
            startingHotelId: startingHotelId || activeCity.hotels[0]?.id || "",
            startTime: startTime || "08:00 AM",
            wheelchairAccessibleOnly: wheelchairOnly,
          }}
          onSelectStrategy={(strategy, savedConfig) => {
            if(savedConfig) { onGenerateItinerary(savedConfig); onClose(); }
            setShowComparisonModal(false);
          }}
        />
      )}
    </div>
  );
};

import { displayNumber } from "../api";
import React, { useState } from "react";
import {
  MapPin,
  Navigation,
  Clock,
  Hotel as HotelIcon,
  Utensils,
  Ticket,
  RotateCcw,
  WifiOff,
  ShieldCheck,
  ChevronRight,
} from "lucide-react";
import type { DayRoute, ItineraryStop } from "../utils/itineraryPlanner";


interface OfflineRouteMapProps {
  dayPlans: DayRoute[];
  cityName: string;
  startingHotelName: string;
  totalDistanceKm: number;
  isOffline?: boolean;
}

export const OfflineRouteMap: React.FC<OfflineRouteMapProps> = ({
  dayPlans,
  cityName,
  startingHotelName,
  totalDistanceKm,
  isOffline = false,
}) => {
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const activeDay = dayPlans[selectedDayIndex] || dayPlans[0];

  if (!activeDay) return null;

  return (
    <div className="bg-white border-2 border-gold p-4 sm:p-6 space-y-6 shadow-sm font-mono text-xs">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b-2 border-gold pb-4">
        <div>
          <div className="flex items-center gap-2 text-gold uppercase tracking-widest text-[11px] font-bold">
            <Navigation className="w-4 h-4 text-gold" />
            <span>Intra-City Circular Route Circuit</span>
          </div>
          <h3 className="font-display text-xl sm:text-2xl text-ink font-bold mt-1">
            {cityName} Circular Route Map
          </h3>
        </div>

        {/* Offline Badge */}
        <div className="flex items-center gap-2">
          {isOffline ? (
            <div className="bg-gold text-ink font-bold px-3 py-1.5 border border-ink text-xs flex items-center gap-1.5 shadow-xs">
              <WifiOff className="w-3.5 h-3.5 text-ink animate-pulse" />
              <span>Offline Map Mode Active</span>
            </div>
          ) : (
            <div className="bg-salt text-ink font-bold px-3 py-1.5 border border-stone/40 text-xs flex items-center gap-1.5">
              <ShieldCheck className="w-3.5 h-3.5 text-gold" />
              <span>Saved Circuit Loaded</span>
            </div>
          )}
        </div>
      </div>

      {/* Day Selector Tabs if multi-day */}
      {dayPlans.length > 1 && (
        <div className="flex flex-wrap items-center gap-2 border-b border-stone/30 pb-3">
          <span className="text-stone text-[11px] font-bold uppercase mr-1">
            Select Day:
          </span>
          {dayPlans.map((day, idx) => (
            <button
              key={day.dayNumber}
              onClick={() => setSelectedDayIndex(idx)}
              className={`px-3 py-1 text-xs font-bold transition-colors cursor-pointer border ${
                selectedDayIndex === idx
                  ? "bg-ink text-gold border-gold"
                  : "bg-salt hover:bg-gold/10 text-charcoal border-stone/30"
              }`}
            >
              Day {day.dayNumber}: {day.dateLabel}
            </button>
          ))}
        </div>
      )}

      <p className="text-stone font-body text-xs leading-relaxed italic border-l-2 border-gold pl-3">
        "Vector-cached circular route sequence guaranteed to display without
        network coverage inside monument vaults, stepwell corridors, and
        sanctuary reserves."
      </p>

      {/* VECTOR SVG SCHEMATIC CIRCUIT GRAPH */}
      <div className="bg-salt border-2 border-stone/30 p-4 relative overflow-hidden space-y-4">
        <div className="absolute inset-0 bg-stepwell-pattern opacity-10 pointer-events-none" />

        <div className="flex items-center justify-between font-bold text-ink text-xs relative z-10 border-b border-stone/20 pb-2">
          <span className="flex items-center gap-1.5">
            <RotateCcw className="w-4 h-4 text-gold" />
            <span>
              Day {activeDay.dayNumber} Loop Diagram: {activeDay.stops.length}{" "}
              Timed Stops
            </span>
          </span>
          <span className="text-stone text-[11px]">
            Est. Circuit: {activeDay.totalKm} km
          </span>
        </div>

        {/* SVG Circuit Path Diagram */}
        <div className="relative z-10 py-4 overflow-x-auto">
          <div className="min-w-[600px] flex items-center justify-between gap-2 px-2">
            {activeDay.stops.map((stop, idx) => {
              const isFirst = idx === 0;
              const isLast = idx === activeDay.stops.length - 1;
              const isMeal = stop.type === "meal";
              const isHotel = stop.type === "hotel";

              return (
                <React.Fragment key={stop.id}>
                  {/* Stop Node */}
                  <div className="flex flex-col items-center text-center space-y-1.5 group max-w-[110px]">
                    <div
                      className={`w-10 h-10 rounded-full border-2 flex items-center justify-center font-bold text-xs transition-transform  shadow-sm ${
                        isHotel
                          ? "bg-ink text-gold border-gold"
                          : isMeal
                            ? "bg-gold text-ink border-ink"
                            : "bg-white text-ink border-gold"
                      }`}
                    >
                      {isHotel ? (
                        <HotelIcon className="w-4 h-4" />
                      ) : isMeal ? (
                        <Utensils className="w-4 h-4" />
                      ) : (
                        <span>#{idx + 1}</span>
                      )}
                    </div>

                    <span
                      className="font-bold text-[11px] text-ink truncate w-full"
                      title={stop.name}
                    >
                      {stop.name}
                    </span>

                    <span className="bg-ink/10 text-ink px-1.5 py-0.5 text-[9px] font-bold border border-ink/20 uppercase">
                      {stop.arrivalTime}
                    </span>
                  </div>

                  {/* Connecting Arrow/Line */}
                  {!isLast && (
                    <div className="flex-1 flex flex-col items-center justify-center space-y-1 px-1 min-w-[30px]">
                      <span className="text-[9px] text-stone font-bold">
                        {stop.legDistanceKm == null ? "Not available" : `${displayNumber(stop.legDistanceKm)} km`}
                      </span>
                      <div className="w-full h-0.5 bg-gold flex items-center justify-center relative">
                        <ChevronRight className="w-4 h-4 text-gold absolute -right-2 top-1/2 -translate-y-1/2" />
                      </div>
                    </div>
                  )}
                </React.Fragment>
              );
            })}
          </div>
        </div>

        <div className="p-2 bg-ink text-salt text-[11px] flex items-center justify-between font-bold relative z-10 border border-gold">
          <span className="flex items-center gap-1.5">
            <RotateCcw className="w-3.5 h-3.5 text-gold" />
            <span>
              Circular Loop Complete: Returns to base stay [{startingHotelName}]
            </span>
          </span>
          <span className="text-gold">0 Km Backlog</span>
        </div>
      </div>

      {/* CACHED TURN-BY-TURN STOP LIST */}
      <div className="space-y-3">
        <h4 className="font-display text-base text-ink font-bold border-b border-stone/30 pb-1">
          Turn-by-Turn Offline Stop Ordering (Day {activeDay.dayNumber})
        </h4>

        <div className="space-y-2.5">
          {activeDay.stops.map((stop, idx) => {
            const stopNum = idx + 1;
            const isHotel = stop.type === "hotel";
            const isMeal = stop.type === "meal";

            return (
              <div
                key={stop.id}
                className={`p-3.5 border flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs ${
                  isMeal
                    ? "bg-amber-50/80 border-gold"
                    : isHotel
                      ? "bg-salt border-stone/40"
                      : "bg-white border-stone/30"
                }`}
              >
                <div className="flex items-start sm:items-center gap-3">
                  <span className="bg-gold text-ink font-bold px-2 py-0.5 text-[11px] border border-ink shrink-0">
                    #{stopNum}
                  </span>

                  <div className="bg-ink text-salt px-2 py-0.5 text-[10px] font-bold border border-gold shrink-0">
                    {stop.arrivalTime} - {stop.departureTime}
                  </div>

                  <div>
                    <div className="font-bold text-ink text-sm flex items-center gap-1.5">
                      {isHotel ? (
                        <HotelIcon className="w-4 h-4 text-ink shrink-0" />
                      ) : isMeal ? (
                        <Utensils className="w-4 h-4 text-gold shrink-0" />
                      ) : (
                        <Ticket className="w-4 h-4 text-madder shrink-0" />
                      )}
                      <span>{stop.name}</span>
                    </div>
                    <span className="text-[10px] text-stone uppercase tracking-wider block">
                      {stop.category} • {stop.location}
                    </span>
                  </div>
                </div>

                <div className="text-right shrink-0 font-bold text-ink text-xs">
                  {stop.cost > 0
                    ? `₹${stop.cost.toLocaleString("en-IN")}`
                    : "Included"}
                  <span className="block text-[10px] font-normal text-stone">
                    {stop.durationMinutes} mins stop
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

