import React, { useState } from 'react';
import { ArrowRight, Compass } from 'lucide-react';
import { motion } from 'motion/react';
import { useLanguage } from '../context/LanguageContext';
import { useCatalog } from "../api";
import type { Destination } from "../api/types";
import { ImageWithFallback } from "./ImageWithFallback";

interface HeroProps {
  onStartPlanning: () => void;
  onExploreClick: () => void;
}

export const Hero: React.FC<HeroProps> = ({ onStartPlanning, onExploreClick }) => {
  const [headlineIndex, setHeadlineIndex] = useState(0);
  const { t, language } = useLanguage();

  const catalog = useCatalog();
  const destinations = catalog.data ?? [];
  const siteCount = destinations.length;
  const countStr = language === 'hi'
    ? String(siteCount).replace(/[0-9]/g, (d) => '०१२३४५६७८९'[parseInt(d, 10)])
    : String(siteCount);

  const HEADLINE_OPTIONS = [
    language === 'hi' ? "गुजरात की योजना, सीढ़ी दर सीढ़ी।" : "Plan Gujarat, terrace by terrace.",
    language === 'hi' ? "नक्काशीदार पत्थर, सफेद रण, पवित्र तट।" : "Carved stone, salt desert, sacred coast.",
    language === 'hi' ? "प्राचीन ज्यामिति द्वारा निर्मित यात्रा।" : "Travel structured by ancient geometry."
  ];

  if(catalog.loading) return <p role="status">Loading destinations...</p>;
  if(catalog.error) return <p role="alert">{catalog.error} <button onClick={catalog.reload}>Retry</button></p>;
  return (
    <section id="hero" className="relative bg-salt text-charcoal pt-10 pb-16 lg:pt-16 lg:pb-24 overflow-hidden border-b border-stone/30">
      
      {/* Background Watermark Chevron Motif with gentle animated pulse */}
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 0.4 }}
        transition={{ duration: 1.2 }}
        className="absolute inset-0 bg-stepwell-pattern pointer-events-none" 
        aria-hidden="true" 
      />

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-8 items-center">
          
          {/* Left Column: Asymmetric Typography & Action */}
          <div className="lg:col-span-7 space-y-6">
            
            {/* Category Subhead / Badge with entry animation */}
            <motion.div 
              initial={{ opacity: 0, y: -12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.1 }}
              className="inline-flex items-center gap-2 px-3 py-1 bg-ink text-salt text-xs font-mono uppercase tracking-widest border border-stone/30 rounded-md"
            >
              <span className="w-2 h-2 bg-gold animate-pulse rounded-full"></span>
              <span>{t('hero.badge', 'Stepwell Geometric Itinerary Engine')}</span>
            </motion.div>

            {/* Headline with interactive headline variant selector */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.2 }}
            >
              <h1 className="font-display text-4xl sm:text-5xl lg:text-6xl text-charcoal leading-[1.08] tracking-tight">
                {HEADLINE_OPTIONS[headlineIndex]}
              </h1>

              {/* Minimal headline toggle pills */}
              <div className="mt-3 flex items-center gap-2">
                <span className="text-[11px] font-mono text-stone uppercase tracking-wider">
                  {language === 'hi' ? 'दृष्टिकोण:' : 'Perspective:'}
                </span>
                {HEADLINE_OPTIONS.map((_, idx) => (
                  <button
                    key={idx}
                    onClick={() => setHeadlineIndex(idx)}
                    className={`h-2 transition-all duration-200 cursor-pointer rounded-full ${
                      headlineIndex === idx ? 'w-8 bg-gold' : 'w-2 bg-stone/40 hover:bg-stone'
