import React, { useState, useEffect, useRef } from "react";
import {
  Play,
  Pause,
  SkipForward,
  RotateCcw,
  Cpu,
  CheckCircle,
  Info,
} from "lucide-react";
import { SVG_COLORS } from "../data/colors";
import { api, useApi } from "../api";

export interface GraphNode {
  id: string;
  name: string;
  shortName: string;
  x: number;
  y: number;
}

export interface GraphEdge {
  from: string;
  to: string;
  distanceKm: number;
}

// Graph presentation from persisted journey legs; no synthetic catalog nodes.
export function getIntraCityGraph(dto: any): { nodes: GraphNode[]; edges: GraphEdge[] } {
  const stops = dto?.days?.flatMap((day: any) => day.stops) ?? [];
  const unique = [...new Map<string, any>(stops.map((stop: any) => [stop.reference_id, stop])).values()];
  const nodes = unique.map((stop, index) => ({id:stop.reference_id,name:stop.name,shortName:stop.name.split(" ")[0],
    x:100 + (index % 4) * 110,y:90 + Math.floor(index / 4) * 90}));
  const edges = (dto?.trip?.generation_summary?.legs ?? []).map((leg: any) => ({from:leg.from,to:leg.to,distanceKm:Number(leg.distance_km)}));
  return {nodes,edges};
}

export interface AlgorithmStep {
  stepIndex: number;
  description: string;
  currentNodeId: string | null;
  visitedNodeIds: string[];
  frontierNodeIds: string[];
  distances: Record<string, number>;
  previous: Record<string, string | null>;
  activeEdge: { from: string; to: string } | null;
  relaxedEdge: { from: string; to: string } | null;
  isComplete: boolean;
  finalPath: string[];
  finalDistance: number;
}

// Dijkstra Algorithm step generator
export function generateDijkstraSteps(
  startId: string = "hotel",
  targetId: string = "resto",
  nodesList: GraphNode[] = [],
  edgesList: GraphEdge[] = [],
): AlgorithmStep[] {
  const steps: AlgorithmStep[] = [];

  const distances: Record<string, number> = {};
  const previous: Record<string, string | null> = {};
  const unvisited = new Set<string>();

  nodesList.forEach((node) => {
    distances[node.id] = Infinity;
    previous[node.id] = null;
    unvisited.add(node.id);
  });

  const effectiveStart = nodesList.some((n) => n.id === startId)
    ? startId
    : nodesList[0]?.id || "hotel";
  const effectiveTarget = nodesList.some((n) => n.id === targetId)
    ? targetId
    : nodesList[nodesList.length - 1]?.id || "resto";

  distances[effectiveStart] = 0;

  const getNeighbors = (nodeId: string) => {
    const neighbors: { neighborId: string; weight: number }[] = [];
    edgesList.forEach((edge) => {
      if (edge.from === nodeId)
        neighbors.push({ neighborId: edge.to, weight: edge.distanceKm });
      else if (edge.to === nodeId)
        neighbors.push({ neighborId: edge.from, weight: edge.distanceKm });
    });
    return neighbors;
  };

  const visitedNodes: string[] = [];
  let frontierNodes: string[] = [effectiveStart];

  // Initial step
  steps.push({
    stepIndex: 0,
    description: `Initialize Dijkstra search from start node (${nodesList.find((n) => n.id === effectiveStart)?.shortName || effectiveStart}). Distance = 0 km.`,
    currentNodeId: effectiveStart,
    visitedNodeIds: [],
    frontierNodeIds: [effectiveStart],
    distances: { ...distances },
    previous: { ...previous },
    activeEdge: null,
    relaxedEdge: null,
    isComplete: false,
    finalPath: [],
    finalDistance: 0,
  });

  while (unvisited.size > 0) {
    // Select unvisited node with smallest distance
    let currentId: string | null = null;
    let minDistance = Infinity;

    unvisited.forEach((nodeId) => {
      if (distances[nodeId] < minDistance) {
        minDistance = distances[nodeId];
        currentId = nodeId;
      }
    });

    if (currentId === null || minDistance === Infinity) {
      break; // Remaining nodes unreachable
    }

    unvisited.delete(currentId);
    if (!visitedNodes.includes(currentId)) {
      visitedNodes.push(currentId);
    }
    frontierNodes = frontierNodes.filter((id) => id !== currentId);

    const currentNodeObj = nodesList.find((n) => n.id === currentId);

    steps.push({
      stepIndex: steps.length,
      description: `Evaluate node [${currentNodeObj?.shortName || currentId}] (shortest distance so far = ${distances[currentId]} km).`,
      currentNodeId: currentId,
      visitedNodeIds: [...visitedNodes],
      frontierNodeIds: [...frontierNodes],
      distances: { ...distances },
      previous: { ...previous },
      activeEdge: null,
      relaxedEdge: null,
      isComplete: false,
      finalPath: [],
      finalDistance: 0,
    });

    // Check if target reached
    if (currentId === effectiveTarget) {
      break;
    }

    // Examine neighbors
    const neighbors = getNeighbors(currentId);
    for (const { neighborId, weight } of neighbors) {
      if (unvisited.has(neighborId)) {
        if (!frontierNodes.includes(neighborId)) {
          frontierNodes.push(neighborId);
        }

        const alt = distances[currentId] + weight;
        const neighborObj = nodesList.find((n) => n.id === neighborId);

        steps.push({
          stepIndex: steps.length,
          description: `Examine edge (${currentNodeObj?.shortName} → ${neighborObj?.shortName}): distance ${distances[currentId]} + ${weight} = ${alt} km.`,
          currentNodeId: currentId,
          visitedNodeIds: [...visitedNodes],
          frontierNodeIds: [...frontierNodes],
          distances: { ...distances },
          previous: { ...previous },
          activeEdge: { from: currentId, to: neighborId },
          relaxedEdge: null,
          isComplete: false,
          finalPath: [],
          finalDistance: 0,
        });

        if (alt < distances[neighborId]) {
          distances[neighborId] = alt;
          previous[neighborId] = currentId;

          steps.push({
            stepIndex: steps.length,
            description: `Relax edge! New shortest path to [${neighborObj?.shortName}] updated to ${alt} km.`,
            currentNodeId: currentId,
            visitedNodeIds: [...visitedNodes],
            frontierNodeIds: [...frontierNodes],
            distances: { ...distances },
            previous: { ...previous },
            activeEdge: { from: currentId, to: neighborId },
            relaxedEdge: { from: currentId, to: neighborId },
            isComplete: false,
            finalPath: [],
            finalDistance: 0,
          });
        }
      }
    }
  }

  // Construct final path
  const finalPath: string[] = [];
  let curr: string | null = effectiveTarget;
  if (distances[effectiveTarget] !== Infinity) {
    while (curr) {
      finalPath.unshift(curr);
      curr = previous[curr];
    }
  }

  const finalDist =
    distances[effectiveTarget] !== Infinity ? distances[effectiveTarget] : 0;

  steps.push({
    stepIndex: steps.length,
    description: `Dijkstra search complete! Shortest path identified (${finalDist} km).`,
    currentNodeId: null,
    visitedNodeIds: [...visitedNodes],
    frontierNodeIds: [],
    distances: { ...distances },
    previous: { ...previous },
    activeEdge: null,
    relaxedEdge: null,
    isComplete: true,
    finalPath,
    finalDistance: Math.round(finalDist * 10) / 10,
  });

  return steps;
}

interface DijkstraVisualizerProps {
  tripId?: string;
  cityId?: string;
  startNodeId?: string;
  targetNodeId?: string;
}

export const DijkstraVisualizer: React.FC<DijkstraVisualizerProps> = ({
  cityId,
  tripId,
  startNodeId,
  targetNodeId,
}) => {
  const request = useApi(signal => api.trip(tripId ?? "", signal), [tripId]);
  const intraGraph = getIntraCityGraph(request.data);
  const activeNodes = intraGraph.nodes;
  const activeEdges = intraGraph.edges;

  const [startId, setStartId] = useState<string>(
    startNodeId || activeNodes[0]?.id || "hotel",
  );
  const [targetId, setTargetId] = useState<string>(
    targetNodeId || activeNodes[activeNodes.length - 1]?.id || "resto",
  );

  const [steps, setSteps] = useState<AlgorithmStep[]>([]);
  const [currentStepIndex, setCurrentStepIndex] = useState<number>(0);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [hasReducedMotion, setHasReducedMotion] = useState<boolean>(false);

  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Check prefers-reduced-motion
  useEffect(() => {
    const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    setHasReducedMotion(mediaQuery.matches);

    const handleChange = (e: MediaQueryListEvent) => {
      setHasReducedMotion(e.matches);
    };

    mediaQuery.addEventListener?.("change", handleChange);
    return () => mediaQuery.removeEventListener?.("change", handleChange);
  }, []);

  useEffect(() => {
    setStartId(startNodeId || activeNodes[0]?.id || "");
    setTargetId(targetNodeId || activeNodes.at(-1)?.id || "");
  }, [request.data]);
  // Regenerate steps when start, target or city changes
  useEffect(() => {
    if(!activeNodes.length || !activeEdges.length) { setSteps([]); return; }
    const generated = generateDijkstraSteps(
      startId,
      targetId,
      activeNodes,
      activeEdges,
    );
    setSteps(generated);

    const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    if (mediaQuery.matches) {
      // If reduced motion, jump straight to final step
      setCurrentStepIndex(generated.length - 1);
      setIsPlaying(false);
    } else {
      setCurrentStepIndex(0);
      setIsPlaying(false);
    }
  }, [startId, targetId, cityId, request.data]);

  // Handle Playback Timer
  useEffect(() => {
    if (isPlaying && steps.length > 0) {
      timerRef.current = setInterval(() => {
        setCurrentStepIndex((prevIndex) => {
          if (prevIndex >= steps.length - 1) {
            setIsPlaying(false);
            if (timerRef.current) clearInterval(timerRef.current);
            return prevIndex;
          }
          return prevIndex + 1;
        });
      }, 700);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isPlaying, steps]);

  const currentStep = steps[currentStepIndex] || steps[0];

  const handlePlayPause = () => {
    if (currentStepIndex >= steps.length - 1) {
      setCurrentStepIndex(0);
    }
    setIsPlaying(!isPlaying);
  };

  const handleStepForward = () => {
    setIsPlaying(false);
    if (currentStepIndex < steps.length - 1) {
      setCurrentStepIndex((prev) => prev + 1);
    }
  };

  const handleReset = () => {
    setIsPlaying(false);
    if (hasReducedMotion) {
      setCurrentStepIndex(steps.length - 1);
    } else {
      setCurrentStepIndex(0);
    }
  };

  if(request.loading) return <p role="status">Loading saved route legs...</p>;
  if(request.error) return <p role="alert">{request.error} <button onClick={request.reload}>Retry</button></p>;
  if (!currentStep) return <p role="status">No persisted travel legs are available to visualize.</p>;

  // Format final path display names
  const pathNames = currentStep.finalPath.map((id) => {
    const n = activeNodes.find((node) => node.id === id);
    return n ? n.shortName : id;
  });

  return (
    <div className="bg-white border-2 border-gold p-4 sm:p-5 space-y-4 shadow-sm relative font-mono text-xs">
      {/* Top Header & Framing Caption */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-stone/30 pb-3">
        <div>
          <div className="flex items-center gap-2 text-gold uppercase tracking-wider text-[11px] font-bold">
            <Cpu className="w-4 h-4 text-gold" />
            <span>Dijkstra Shortest-Path Algorithm Engine</span>
          </div>
          <h4 className="font-display text-lg text-ink font-bold">
            Live Graph Execution Matrix
          </h4>
        </div>

        {/* Start / Target Selector */}
        <div className="flex items-center gap-2 text-[11px]">
          <span className="text-stone font-bold uppercase">Route:</span>
          <select
            value={startId}
            onChange={(e) => setStartId(e.target.value)}
            aria-label="Select start node for route calculation"
            className="bg-salt border border-stone/40 text-charcoal font-mono px-2 py-1 text-[11px] outline-none"
          >
            {activeNodes.map((n) => (
              <option key={n.id} value={n.id}>
                Start: {n.shortName}
              </option>
            ))}
          </select>
          <span className="text-madder font-bold">→</span>
          <select
            value={targetId}
            onChange={(e) => setTargetId(e.target.value)}
            aria-label="Select target node for route calculation"
            className="bg-salt border border-stone/40 text-charcoal font-mono px-2 py-1 text-[11px] outline-none"
          >
            {activeNodes.map((n) => (
              <option key={n.id} value={n.id}>
                Target: {n.shortName}
              </option>
            ))}
          </select>
        </div>
      </div>

      <p className="text-[11px] font-body text-stone italic border-l-2 border-gold pl-2">
        "Dijkstra finds the shortest path between two attractions when they
        aren't directly connected -- most stops in your route are direct, this
        shows what happens when one isn't."
      </p>

      {/* Reduced Motion Warning Note */}
      {hasReducedMotion && (
        <div className="p-2.5 bg-ink text-salt border border-stone/40 text-[11px] flex items-center gap-2">
          <Info className="w-4 h-4 text-gold shrink-0" />
          <span>
            Animation reduced per your system settings. Displaying computed
            final shortest path directly.
          </span>
        </div>
      )}

      {/* SVG GRAPH CANVAS */}
      <div className="bg-salt/90 border-2 border-stone/30 relative h-[320px] sm:h-[350px] w-full overflow-auto p-2 shadow-inner">
        <div className="absolute inset-0 bg-stepwell-pattern opacity-10 pointer-events-none" />

        <svg
          className="w-full h-full"
          viewBox="0 0 500 360"
          preserveAspectRatio="xMidYMid meet"
          aria-label="Interactive Dijkstra Graph Visualization"
        >
          {/* 1. DRAW ALL GRAPH EDGES */}
          {activeEdges.map((edge, edgeIndex) => {
            const fromNode = activeNodes.find((n) => n.id === edge.from);
            const toNode = activeNodes.find((n) => n.id === edge.to);
            if (!fromNode || !toNode) return null;

            // Check if this edge is part of the final shortest path
            const isInFinalPath =
              currentStep.isComplete &&
              currentStep.finalPath.some((id, idx) => {
                if (idx === currentStep.finalPath.length - 1) return false;
                const nextId = currentStep.finalPath[idx + 1];
                return (
                  (id === edge.from && nextId === edge.to) ||
                  (id === edge.to && nextId === edge.from)
                );
              });

            // Check if edge is currently active/relaxed
            const isActive =
              currentStep.activeEdge &&
              ((currentStep.activeEdge.from === edge.from &&
                currentStep.activeEdge.to === edge.to) ||
                (currentStep.activeEdge.from === edge.to &&
                  currentStep.activeEdge.to === edge.from));

            const isRelaxed =
              currentStep.relaxedEdge &&
              ((currentStep.relaxedEdge.from === edge.from &&
                currentStep.relaxedEdge.to === edge.to) ||
                (currentStep.relaxedEdge.from === edge.to &&
                  currentStep.relaxedEdge.to === edge.from));

            let strokeColor: string = SVG_COLORS.stone; // default neutral stone
            let strokeWidth = 1.5;
            let strokeDash = "4 3";

            if (isInFinalPath) {
              strokeColor = SVG_COLORS.madder; // Madder Red solid
              strokeWidth = 3.5;
              strokeDash = "none";
            } else if (isRelaxed || isActive) {
              strokeColor = SVG_COLORS.madder; // Highlight edge in Madder Red
              strokeWidth = 3;
              strokeDash = "none";
            }

            const midX = (fromNode.x + toNode.x) / 2;
            const midY = (fromNode.y + toNode.y) / 2;

            return (
              <g key={`${edge.from}-${edge.to}-${edgeIndex}`}>
                <line
                  x1={fromNode.x}
                  y1={fromNode.y}
                  x2={toNode.x}
                  y2={toNode.y}
                  stroke={strokeColor}
                  strokeWidth={strokeWidth}
                  strokeDasharray={strokeDash}
                  className="transition-all duration-300"
                />

                {/* Distance Label Badge */}
                <rect
                  x={midX - 14}
                  y={midY - 8}
                  width="28"
                  height="14"
                  fill={SVG_COLORS.salt}
                  stroke={SVG_COLORS.stone}
                  rx="2"
                />
                <text
                  x={midX}
                  y={midY + 3}
                  textAnchor="middle"
                  fill={SVG_COLORS.charcoal}
                  fontSize="8"
                  fontFamily="IBM Plex Mono, monospace"
                  fontWeight="600"
                >
                  {edge.distanceKm}k
                </text>
              </g>
            );
          })}

          {/* 2. DRAW GRAPH NODES */}
          {activeNodes.map((node) => {
            const isStart = node.id === startId;

            const isCurrent = currentStep.currentNodeId === node.id;
            const isVisited = currentStep.visitedNodeIds.includes(node.id);
            const isFrontier = currentStep.frontierNodeIds.includes(node.id);
            const isInFinalPath =
              currentStep.isComplete && currentStep.finalPath.includes(node.id);

            let fillColor: string = SVG_COLORS.white; // default
            let strokeColor: string = SVG_COLORS.stone;
            let textColor: string = SVG_COLORS.charcoal;
            let isPulsing = false;

            if (isCurrent) {
              fillColor = SVG_COLORS.gold; // Stepwell Gold highlight for active node
              strokeColor = SVG_COLORS.ink;
              textColor = SVG_COLORS.ink;
            } else if (isInFinalPath) {
              fillColor = SVG_COLORS.madder; // Madder Red for path
              strokeColor = SVG_COLORS.gold;
              textColor = SVG_COLORS.white;
            } else if (isVisited) {
              fillColor = SVG_COLORS.ink; // Ink Indigo for visited
              strokeColor = SVG_COLORS.gold;
              textColor = SVG_COLORS.salt;
            } else if (isFrontier) {
              fillColor = SVG_COLORS.stone; // Stone Grey for frontier
              strokeColor = SVG_COLORS.gold;
              textColor = SVG_COLORS.charcoal;
              isPulsing = true;
            } else if (isStart) {
              fillColor = SVG_COLORS.gold;
              strokeColor = SVG_COLORS.ink;
            }

            const distVal = currentStep.distances[node.id];
            const distLabel = distVal === Infinity ? "∞" : `${distVal}k`;

            return (
              <g
                key={node.id}
                transform={`translate(${node.x}, ${node.y})`}
                className="transition-all duration-300 cursor-pointer"
              >
                {/* Outer Pulse Circle if Frontier */}
                {isPulsing && !hasReducedMotion && (
                  <circle
                    r="18"
                    fill="none"
                    stroke={SVG_COLORS.gold}
                    strokeWidth="1.5"
                    className="animate-ping opacity-60"
                  />
                )}

                {/* Node Circle */}
                <circle
                  r="14"
                  fill={fillColor}
                  stroke={strokeColor}
                  strokeWidth={isCurrent || isInFinalPath ? "3" : "2"}
                  className="transition-colors duration-300 shadow-md"
                />

                {/* Node Label Text */}
                <text
                  textAnchor="middle"
                  dy="4"
                  fill={textColor}
                  fontSize="9"
                  fontFamily="IBM Plex Mono, monospace"
                  fontWeight="bold"
                >
                  {node.shortName.substring(0, 3).toUpperCase()}
                </text>

                {/* Node Title & Distance Subtitle */}
                <text
                  textAnchor="middle"
                  y="26"
                  fill={SVG_COLORS.charcoal}
                  fontSize="9"
                  fontFamily="IBM Plex Mono, monospace"
                  fontWeight="bold"
                >
                  {node.shortName}
                </text>
                <text
                  textAnchor="middle"
                  y="36"
                  fill={SVG_COLORS.madder}
                  fontSize="8"
                  fontFamily="IBM Plex Mono, monospace"
                  fontWeight="600"
                >
                  [{distLabel}]
                </text>
              </g>
            );
          })}
        </svg>
      </div>

      {/* Step Description Line */}
      <div
        aria-live="polite"
        className="p-3 bg-ink text-salt border border-gold text-xs flex items-center justify-between gap-2"
      >
        <div className="flex items-center gap-2 truncate">
          <span className="bg-gold text-ink font-bold px-2 py-0.5 text-[10px] uppercase shrink-0">
            Step {currentStepIndex + 1}/{steps.length}
          </span>
          <span className="truncate text-stone text-[11px]">
            {currentStep.description}
          </span>
        </div>
        {currentStep.isComplete && (
          <span className="text-gold font-bold flex items-center gap-1 shrink-0 text-[11px]">
            <CheckCircle className="w-3.5 h-3.5 text-gold" />
            <span>Path Found</span>
          </span>
        )}
      </div>

      {/* Final Shortest Path Summary Line */}
      {currentStep.isComplete && currentStep.finalPath.length > 0 && (
        <div className="p-3 bg-madder/10 border border-madder text-ink font-mono text-xs font-bold flex flex-wrap items-center justify-between gap-2 animate-fadeIn">
          <div className="flex items-center gap-2">
            <span className="text-madder uppercase font-bold text-[10px] bg-madder text-salt px-2 py-0.5">
              Shortest Path
            </span>
            <span>{pathNames.join(" → ")}</span>
          </div>
          <div className="text-madder text-sm">
            · {currentStep.finalDistance} km
          </div>
        </div>
      )}

      {/* PLAYBACK CONTROLS: Play, Pause, Step Forward, Reset */}
      <div className="flex flex-wrap items-center justify-between gap-3 pt-2 border-t border-stone/30">
        <div className="flex items-center gap-2">
          {/* Play/Pause Button */}
          <button
            onClick={handlePlayPause}
            aria-label={
              isPlaying
                ? "Pause algorithm execution"
                : "Play algorithm execution"
            }
            className="bg-ink hover:bg-ink/90 text-salt border border-gold px-3 py-1.5 text-xs font-mono font-bold flex items-center gap-1.5 transition-colors cursor-pointer"
          >
            {isPlaying ? (
              <>
                <Pause className="w-3.5 h-3.5 text-gold" />
                <span>Pause</span>
              </>
            ) : (
              <>
                <Play className="w-3.5 h-3.5 text-gold" />
                <span>Play</span>
              </>
            )}
          </button>

          {/* Step Forward Button */}
          <button
            onClick={handleStepForward}
            disabled={currentStepIndex >= steps.length - 1}
            aria-label="Step forward to next step"
            className="bg-salt hover:bg-stone/20 text-charcoal border border-stone/40 px-3 py-1.5 text-xs font-mono font-bold flex items-center gap-1.5 transition-colors cursor-pointer disabled:opacity-40"
          >
            <SkipForward className="w-3.5 h-3.5 text-ink" />
            <span>Step forward</span>
          </button>

          {/* Reset Button */}
          <button
            onClick={handleReset}
            aria-label="Reset algorithm to step 1"
            className="bg-salt hover:bg-stone/20 text-charcoal border border-stone/40 px-3 py-1.5 text-xs font-mono font-bold flex items-center gap-1.5 transition-colors cursor-pointer"
          >
            <RotateCcw className="w-3.5 h-3.5 text-stone" />
            <span>Reset</span>
          </button>
        </div>

        {/* Color Legend */}
        <div className="flex flex-wrap items-center gap-3 text-[10px] text-stone">
          <span className="flex items-center gap-1">
            <span className="w-2.5 h-2.5 rounded-full bg-gold inline-block border border-ink" />{" "}
            Start/Current
          </span>
          <span className="flex items-center gap-1">
            <span className="w-2.5 h-2.5 rounded-full bg-stone/50 inline-block border border-gold" />{" "}
            Frontier
          </span>
          <span className="flex items-center gap-1">
            <span className="w-2.5 h-2.5 rounded-full bg-ink inline-block border border-gold" />{" "}
            Visited
          </span>
          <span className="flex items-center gap-1">
            <span className="w-2.5 h-2.5 rounded-full bg-madder inline-block border border-gold" />{" "}
            Path
          </span>
        </div>
      </div>
    </div>
  );
};

frontend/src/components/DestinationDetai:
import { displayNumber } from "../api";
import React, { useState } from "react";
import { api, useApi, EMPTY_DESTINATION } from "../api";
import type { Destination } from "../api/types";
import {
  ArrowLeft,
  Star,
  MapPin,
  Clock,
  Ticket,
  Calendar,
  ShieldCheck,
  Hotel,
  PlusCircle,
  CheckCircle2,
  ChevronRight,
  Compass,
  Accessibility,
  Hospital,
  Shield,
} from "lucide-react";
import { useLanguage } from "../context/LanguageContext";
import { AccessibilityBadge } from "./AccessibilityBadge";
import { BestTimeNote } from "./BestTimeNote";
import { ImageWithFallback } from "./ImageWithFallback";

interface DestinationDetailViewProps {
  destination: Destination;
  preferredHotels?: Record<string, string>;
  onSelectPreferredHotel?: (cityId: string, hotelId: string) => void;
  onBack: () => void;
  onAddToTrip: (dest: Destination) => void;
  isAddedToTrip: boolean;
  onSelectNearbyDestination?: (destId: string) => void;
  onOpenPlannerWithSite?: (dest: Destination) => void;
}

// Note: Full content translation of long narrative descriptions, hotel bios, and attraction details
// is reserved for a follow-up content pass. Core UI labels, headings, buttons, and site/attraction names use active localization.

export const DestinationDetailView: React.FC<DestinationDetailViewProps> = ({
  destination: requestedDestination,
  preferredHotels,
  onSelectPreferredHotel,
  onBack,
  onAddToTrip,
  isAddedToTrip,
  onSelectNearbyDestination,
  onOpenPlannerWithSite,
}) => {
  const { language, t, getName } = useLanguage();
  const request = useApi(signal => api.destination(requestedDestination.id, signal), [requestedDestination.id]);
  const destination = request.data ?? EMPTY_DESTINATION;
  const [wheelchairOnly, setWheelchairOnly] = useState<boolean>(false);
  const [selectedDemands, setSelectedDemands] = useState<
    ("low" | "moderate" | "high")[]
  >([]);

  const toggleDemandFilter = (level: "low" | "moderate" | "high") => {
    setSelectedDemands((prev) =>
      prev.includes(level) ? prev.filter((d) => d !== level) : [...prev, level],
    );
  };

  const filteredAttractions = (destination.attractions || []).filter((attr) => {
    if (wheelchairOnly && !attr.wheelchairAccessible) return false;
    if (
      selectedDemands.length > 0 &&
      !selectedDemands.includes(attr.physicalDemand)
    )
      return false;
    return true;
  });

  if (request.loading) return <p role="status">Loading destination...</p>;
  if (request.error) return <p role="alert">{request.error} <button onClick={request.reload}>Retry</button></p>;
  return (
    <div className="bg-salt min-h-screen border-b border-stone/30 animate-fadeIn">
      {/* 1. FULL-WIDTH HERO IMAGE BAND */}
      <div className="relative h-80 sm:h-96 md:h-[480px] w-full bg-ink overflow-hidden">
        {/* Background Image */}
        <ImageWithFallback
          src={destination.imageUrl}
          alt={destination.imageAlt || getName(destination)}
          category={destination.officialCategory || destination.category}
          className="w-full h-full object-cover hover:scale-105 transition-all duration-700"
        />

        {/* Ink Indigo Gradient Overlay at bottom edge for crisp text contrast */}
        <div className="absolute inset-0 bg-gradient-to-t from-ink via-ink/40 to-transparent" />

        {/* Top Floating Back Breadcrumb */}
        <div className="absolute top-6 left-4 sm:left-6 lg:left-8 z-20">
          <button
            onClick={onBack}
            className="inline-flex items-center gap-2 bg-ink/80 hover:bg-ink text-salt border border-stone/40 hover:border-gold text-xs font-mono px-3.5 py-1.5 backdrop-blur-sm transition-colors cursor-pointer rounded-lg shadow-xs"
          >
            <ArrowLeft className="w-3.5 h-3.5 text-gold" />
            <span>
              {language === "hi"
                ? "सभी स्थलों पर वापस जाएं"
                : "Back to All Destinations"}
            </span>
          </button>
        </div>

        {/* Overlaid Hero Content */}
        <div className="absolute bottom-0 inset-x-0 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pb-8 z-10 space-y-3">
          <div className="flex flex-wrap items-center gap-2">
            <span className="bg-gold text-ink font-mono text-[11px] font-bold px-3 py-1 uppercase tracking-wider rounded-md">
              {destination.officialCategory}
            </span>
            <span className="bg-ink/80 text-salt font-mono text-[11px] px-3 py-1 border border-stone/40 uppercase rounded-md">
              {destination.district}{" "}
              {language === "hi" ? "ज़िला" : "District"}
            </span>
            <span className="text-gold font-mono text-sm font-bold flex items-center gap-1 bg-ink/80 px-2.5 py-0.5 border border-gold/40 rounded-md">
              <Star className="w-3.5 h-3.5 fill-gold text-gold" />
              {destination.rating}
            </span>
          </div>

          <h1 className="font-display text-3xl sm:text-5xl lg:text-6xl text-salt font-bold tracking-tight leading-tight">
            {getName(destination)}
          </h1>

          <p className="font-mono text-xs text-stone/90 max-w-2xl flex items-center gap-2">
            <Compass className="w-4 h-4 text-gold shrink-0" />
            <span>
              {destination.tag} • {destination.distanceFromAhmedabad}{" "}
              {language === "hi" ? "अहमदाबाद से" : "from Ahmedabad"}
            </span>
          </p>
        </div>
      </div>

      {/* 1.5 SEASONAL ADVISORY BANNER */}
      {destination.seasonalAdvisory &&
        (() => {
          const nowMonth = new Date().getMonth() + 1; // 1..12
          const isActive = destination.seasonalAdvisory.activeMonths.some(
            (m) => {
              const diff = Math.abs(m - nowMonth);
              return diff === 0 || diff === 1 || diff === 11;
            },
          );
          if (!isActive) return null;

          return (
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-6 -mb-4">
              <div className="bg-white border-l-4 border-gold border-y border-r border-stone/30 p-4 sm:p-5 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 shadow-sm rounded-xl">
                <div className="flex items-start gap-3">
                  <Calendar className="w-5 h-5 text-gold shrink-0 mt-0.5" />
                  <div className="space-y-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="font-mono text-xs font-bold text-gold uppercase tracking-wider">
                        {language === "hi"
                          ? "मौसमी यात्रा सलाह"
                          : "Seasonal Travel Advisory"}
                      </span>
                      {destination.seasonalAdvisory.peakWindowLabel && (
                        <span className="bg-gold/10 text-gold border border-gold/30 font-mono text-[10px] px-2 py-0.5 rounded-md font-medium">
                          {destination.seasonalAdvisory.peakWindowLabel}
                        </span>
                      )}
                    </div>
                    <p className="text-xs sm:text-sm text-charcoal/90 font-body leading-relaxed">
                      {destination.seasonalAdvisory.note}
                    </p>
                  </div>
                </div>
              </div>
            </div>
          );
        })()}

      {/* 2. TWO-COLUMN MAIN CONTENT LAYOUT */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10 lg:py-14">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 lg:gap-12 items-start">
          {/* LEFT COLUMN (WIDER - lg:col-span-8) */}
          <div className="lg:col-span-8 space-y-10">
            {/* Detailed Description Section */}
            <div className="bg-white p-6 sm:p-8 border border-stone/30 space-y-6 shadow-sm rounded-2xl">
              <div>
                <span className="font-mono text-xs text-gold uppercase tracking-widest block mb-1">
                  {language === "hi"
                    ? "ऐतिहासिक विवरण और वास्तुकला समीक्षा"
                    : "Heritage Monograph & Architectural Overview"}
                </span>
                <h2 className="font-display text-2xl sm:text-3xl text-charcoal font-bold">
                  {language === "hi"
                    ? `${getName(destination)} के बारे में`
                    : `About ${getName(destination)}`}
                </h2>
              </div>

              <p className="text-stone/90 text-sm sm:text-base leading-relaxed font-body">
                {destination.description}
              </p>

              {/* Highlights List */}
              {destination.highlights && destination.highlights.length > 0 && (
                <div className="pt-4 border-t border-stone/20 space-y-3">
                  <h3 className="font-mono text-xs text-charcoal uppercase tracking-wider font-semibold">
                    {language === "hi"
                      ? "प्रमुख ऐतिहासिक और वास्तुशिल्प विशेषताएं:"
                      : "Key Historical & Architectural Highlights:"}
                  </h3>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                    {destination.highlights.map((item, idx) => (
                      <div
                        key={idx}
                        className="flex items-center gap-2 text-xs font-mono text-stone bg-salt/60 p-2.5 border border-stone/20 rounded-lg"
                      >
                        <ShieldCheck className="w-4 h-4 text-gold shrink-0" />
                        <span>{item}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Visiting Information Panel */}
            <div className="bg-ink text-salt p-6 sm:p-8 border border-stone/40 space-y-6 rounded-2xl shadow-md">
              <span className="font-mono text-xs text-gold uppercase tracking-widest block">
                {language === "hi"
                  ? "सैलानी अनुभव और समय सारिणी"
                  : "Visitor Experience & Timing Parameters"}
              </span>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 font-mono text-xs">
                <div className="space-y-1 border-l-2 border-gold pl-3">
                  <span className="text-stone uppercase text-[10px]">
                    {language === "hi"
                      ? "उत्तम समय"
                      : "Best Season"}
                  </span>
                  <div className="font-bold text-salt text-sm flex items-center gap-1.5">
                    <Calendar className="w-4 h-4 text-gold shrink-0" />
                    <span>{destination.bestTime}</span>
                  </div>
                  <p className="text-[11px] text-stone/80">
                    {language === "hi"
                      ? "अनुकूल मौसम"
                      : "Optimal climate for heritage walks"}
                  </p>
                </div>

                <div className="space-y-1 border-l-2 border-gold pl-3">
                  <span className="text-stone uppercase text-[10px]">
                    {language === "hi"
                      ? "औसत समय"
                      : "Avg Visit Time"}
                  </span>
                  <div className="font-bold text-salt text-sm flex items-center gap-1.5">
                    <Clock className="w-4 h-4 text-gold shrink-0" />
                    <span>{destination.avgVisitTime}</span>
                  </div>
                  <p className="text-[11px] text-stone/80">
                    {language === "hi"
                      ? "अनुशंसित समय अवधि"
                      : "Recommended exploration duration"}
                  </p>
                </div>

                <div className="space-y-1 border-l-2 border-gold pl-3">
                  <span className="text-stone uppercase text-[10px]">
                    {language === "hi"
                      ? "प्रवेश टिकट"
                      : "Entry Ticket"}
                  </span>
                  <div className="font-bold text-gold text-sm flex items-center gap-1.5">
                    <Ticket className="w-4 h-4 text-gold shrink-0" />
                    <span>{destination.entryFee}</span>
                  </div>
                  <p className="text-[11px] text-stone/80">
                    Official ASI / TCGL tariff
                  </p>
                </div>
              </div>

              {/* Safety & Essential Services Block */}
              {(destination.nearestHospital ||
                destination.nearestPoliceStation) && (
                <div className="pt-4 border-t border-stone/30 font-mono text-xs text-stone space-y-1.5">
                  <span className="text-[11px] uppercase tracking-wider font-semibold text-stone/90 block">
                    Good to know.
                  </span>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-stone/90 text-[11px]">
                    {destination.nearestHospital && (
                      <div className="flex items-center gap-1.5">
                        <Hospital className="w-3.5 h-3.5 text-stone shrink-0" />
                        <span>
                          Nearest hospital: {destination.nearestHospital}
                        </span>
                      </div>
                    )}
                    {destination.nearestPoliceStation && (
                      <div className="flex items-center gap-1.5">
                        <Shield className="w-3.5 h-3.5 text-stone shrink-0" />
                        <span>
                          Nearest police: {destination.nearestPoliceStation}
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* INTRA-CITY MONUMENTS & ATTRACTIONS WITH ACCESSIBILITY FILTERS */}
            {destination.attractions && destination.attractions.length > 0 && (
              <div className="bg-white p-6 sm:p-8 border border-stone/30 space-y-6 shadow-sm rounded-2xl">
                <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 border-b border-stone/20 pb-4">
                  <div>
                    <span className="font-mono text-xs text-gold uppercase tracking-widest block mb-1">
                      {language === "hi"
                        ? "शहर के स्मारक और आकर्षण"
                        : "Monuments & Intra-City Heritage Attractions"}
                    </span>
                    <h3 className="font-display text-2xl sm:text-3xl text-charcoal font-bold">
                      {language === "hi"
                        ? `${getName(destination)} मुख्य आकर्षण`
                        : `Key Monuments in ${getName(destination)}`}
                    </h3>
                  </div>
                  <span className="font-mono text-xs text-stone">
                    Showing {filteredAttractions.length} of{" "}
                    {destination.attractions.length} sites
                  </span>
                </div>

                {/* Accessibility Filter Chips Toolbar */}
                <div className="flex flex-wrap items-center gap-2 sm:gap-3 p-3 bg-salt border border-stone/20 font-mono text-xs rounded-xl">
                  <button
                    type="button"
                    onClick={() => setWheelchairOnly(!wheelchairOnly)}
                    className={`inline-flex items-center gap-1.5 px-3 py-1.5 border transition-all cursor-pointer font-semibold rounded-lg ${
                      wheelchairOnly
                        ? "bg-emerald-800 text-salt border-emerald-900 shadow-xs"
                        : "bg-white text-emerald-950 border-emerald-400 hover:bg-emerald-50"
                    }`}
                  >
                    <Accessibility
                      className={`w-4 h-4 ${wheelchairOnly ? "text-emerald-300" : "text-emerald-700"}`}
                    />
                    <span>Wheelchair Accessible</span>
                    {wheelchairOnly && (
                      <span className="text-[10px] bg-emerald-950 text-salt px-1 rounded-sm">
                        ACTIVE
                      </span>
                    )}
                  </button>

                  <span className="text-stone/40 hidden sm:inline">|</span>

                  <div className="flex flex-wrap items-center gap-1.5">
                    <span className="text-stone font-semibold uppercase text-[10px]">
                      Physical Demand:
                    </span>
                    {(["low", "moderate", "high"] as const).map((level) => {
                      const isSelected = selectedDemands.includes(level);
                      const badgeStyle =
                        level === "low"
                          ? isSelected
                            ? "bg-emerald-800 text-salt border-emerald-900"
                            : "bg-white text-emerald-900 border-stone/30 hover:border-emerald-500"
                          : level === "moderate"
                            ? isSelected
                              ? "bg-amber-800 text-salt border-amber-900"
                              : "bg-white text-amber-900 border-stone/30 hover:border-amber-500"
                            : isSelected
                              ? "bg-madder text-salt border-red-900"
                              : "bg-white text-madder border-stone/30 hover:border-red-500";

                      return (
                        <button
                          key={level}
                          type="button"
                          onClick={() => toggleDemandFilter(level)}
                          className={`inline-flex items-center gap-1 px-2.5 py-1 border text-[10px] uppercase transition-all cursor-pointer font-bold rounded-lg ${badgeStyle}`}
                        >
                          <span>{level}</span>
                        </button>
                      );
                    })}
                  </div>

                  {(wheelchairOnly || selectedDemands.length > 0) && (
                    <button
                      type="button"
                      onClick={() => {
                        setWheelchairOnly(false);
                        setSelectedDemands([]);
                      }}
                      className="text-stone hover:text-madder text-[10px] underline ml-auto uppercase font-semibold cursor-pointer"
                    >
                      Reset Filters
                    </button>
                  )}
                </div>

                {/* Attraction Cards Grid */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {filteredAttractions.map((attr) => (
                    <div
                      key={attr.id}
                      className="bg-salt border border-stone/30 p-4 space-y-3 hover:border-gold transition-colors flex flex-col justify-between overflow-hidden rounded-xl"
                    >
                      {attr.imageUrl && (
                        <div className="h-36 sm:h-40 overflow-hidden relative -mx-4 -mt-4 mb-2 border-b border-stone/20 bg-charcoal rounded-t-xl">
                          <ImageWithFallback
                            src={attr.imageUrl}
                            alt={getName(attr)}
                            category={attr.category}
                            className="w-full h-full object-cover hover:scale-105 transition-transform duration-500 rounded-t-xl"
                          />
                        </div>
                      )}
                      <div className="space-y-2">
                        <div className="flex items-center justify-between">
                          <span className="font-mono text-[10px] text-gold uppercase font-bold tracking-wider rounded-md">
                            {attr.category}
                          </span>
                          <span className="font-mono text-xs text-gold font-bold flex items-center gap-1 rounded-md">
                            <Star className="w-3.5 h-3.5 fill-gold text-gold" />
                            {displayNumber(attr.rating)}
                          </span>
                        </div>

                        <h4 className="font-display text-base font-bold text-charcoal">
                          {getName(attr)}
                        </h4>
                        <BestTimeNote note={attr.bestTimeNote} />

                        <p className="text-xs text-stone line-clamp-2">
                          {attr.description}
                        </p>
                      </div>

                      <div className="space-y-2.5 pt-2 border-t border-stone/20">
                        {/* Accessibility Badges */}
                        <AccessibilityBadge
                          wheelchairAccessible={attr.wheelchairAccessible}
                          physicalDemand={attr.physicalDemand}
                        />

                        <div className="flex items-center justify-between font-mono text-[11px] text-stone">
                          <span>
                            Fee:{" "}
                            <strong className="text-charcoal">
                              {attr.entryFee}
                            </strong>
                          </span>
                          <span>
                            Time:{" "}
                            <strong className="text-charcoal">
                              {attr.durationHours}h
                            </strong>
                          </span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* NEARBY ATTRACTIONS TERRACE-MINI-GRID */}
            {destination.nearbyAttractions &&
              destination.nearbyAttractions.length > 0 && (
                <div className="space-y-4">
                  <div className="border-l-2 border-gold pl-3">
                    <span className="font-mono text-xs text-gold uppercase tracking-widest block">
                      {language === "hi"
                        ? "क्षेत्रीय सर्किट"
                        : "Regional Circuit"}
                    </span>
                    <h3 className="font-display text-2xl text-charcoal font-bold">
                      {language === "hi"
                        ? "निकटतम स्मारक और आकर्षण"
                        : "Nearby Monuments & Heritage Attractions"}
                    </h3>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {destination.nearbyAttractions.map((attraction) => (
                      <div
                        key={attraction.id}
                        onClick={() =>
                          onSelectNearbyDestination &&
                          onSelectNearbyDestination(attraction.id)
                        }
                        className="group bg-white p-3.5 border border-stone/30 hover:border-gold transition-all duration-200 cursor-pointer flex gap-3 items-center rounded-xl"
                      >
                        <ImageWithFallback
                          src={attraction.imageUrl}
                          alt={getName(attraction)}
                          category={attraction.category}
                          className="w-20 h-20 object-cover group-hover:scale-105 transition-all shrink-0 border border-stone/20 rounded-lg"
                        />
                        <div className="space-y-1 flex-1 min-w-0">
                          <span className="text-[10px] font-mono text-gold uppercase block truncate">
                            {attraction.category}
                          </span>
                          <h4 className="font-display text-base font-bold text-charcoal group-hover:text-gold transition-colors truncate">
                            {getName(attraction)}
                          </h4>
                          <span className="text-xs font-mono text-stone flex items-center gap-1">
                            <MapPin className="w-3 h-3 text-gold" />
                            {attraction.distance}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
          </div>

          {/* RIGHT COLUMN (NARROWER - lg:col-span-4, STICKY ON DESKTOP) */}
          <div className="lg:col-span-4 lg:sticky lg:top-24 space-y-6">
            <div className="bg-ink text-salt p-6 border-2 border-gold/60 space-y-6 shadow-md rounded-2xl">
              <div className="border-b border-stone/30 pb-4">
                <span className="font-mono text-xs text-gold uppercase tracking-wider block mb-1">
                  {language === "hi"
                    ? "आधिकारिक सारांश"
                    : "Official Heritage Summary"}
                </span>
                <h3 className="font-display text-2xl font-bold text-salt">
                  {getName(destination)}
                </h3>
              </div>

              {/* IBM Plex Mono Logistical Specs Panel */}
              <div className="space-y-3 font-mono text-xs">
                <div className="flex items-center justify-between py-2 border-b border-stone/30">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "प्रवेश शुल्क"
                      : "Entry Fee"}
                  </span>
                  <span className="text-gold font-bold">
                    {destination.entryFee}
                  </span>
                </div>

                <div className="flex items-center justify-between py-2 border-b border-stone/30">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "औसत समय"
                      : "Avg Visit Time"}
                  </span>
                  <span className="text-salt font-semibold">
                    {destination.avgVisitTime}
                  </span>
                </div>

                <div className="flex items-center justify-between py-2 border-b border-stone/30">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "ज़िला"
                      : "District"}
                  </span>
                  <span className="text-salt font-semibold">
                    {destination.district}
                  </span>
                </div>

                <div className="flex items-center justify-between py-2 border-b border-stone/30">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "श्रेणी"
                      : "Category"}
                  </span>
                  <span className="text-salt font-semibold text-[11px] truncate max-w-[150px]">
                    {destination.officialCategory}
                  </span>
                </div>

                <div className="flex items-center justify-between py-2 border-b border-stone/30">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "अहमदाबाद से"
                      : "From Ahmedabad"}
                  </span>
                  <span className="text-salt font-semibold">
                    {destination.distanceFromAhmedabad}
                  </span>
                </div>

                <div className="flex items-center justify-between py-2">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "रेटिंग"
                      : "Visitor Rating"}
                  </span>
                  <span className="text-gold font-bold">
                    {destination.rating}
                  </span>
                </div>
              </div>

              {/* MADDER RED ACTION BUTTON: "Add to Trip Plan" */}
              <div className="space-y-2 pt-2">
                <button
                  onClick={() => onAddToTrip(destination)}
                  className={`w-full py-3.5 px-4 text-xs font-mono uppercase tracking-wider font-bold transition-all duration-200 flex items-center justify-center gap-2 border cursor-pointer rounded-lg shadow-xs ${
                    isAddedToTrip
                      ? "bg-emerald-800 text-salt border-emerald-600"
                      : "bg-madder hover:bg-madder/90 text-salt border-madder"
                  }`}
                >
                  {isAddedToTrip ? (
                    <>
                      <CheckCircle2 className="w-4 h-4 text-emerald-300" />
                      <span>
                        {language === "hi"
                          ? "योजना में जोड़ा गया"
                          : "Added to Trip Plan"}
                      </span>
                    </>
                  ) : (
                    <>
                      <PlusCircle className="w-4 h-4 text-salt" />
                      <span>{t("explore.plan", "Add to Trip Plan")}</span>
                    </>
                  )}
                </button>

                {onOpenPlannerWithSite && (
                  <button
                    onClick={() => onOpenPlannerWithSite(destination)}
                    className="w-full py-2.5 px-4 bg-transparent hover:bg-salt/10 text-gold hover:text-salt border border-gold/40 text-xs font-mono uppercase tracking-wider font-semibold transition-colors flex items-center justify-center gap-1.5 cursor-pointer rounded-lg"
                  >
                    <span>
                      {language === "hi"
                        ? "कस्टम यात्रा प्लान करें"
                        : "Build Custom Itinerary"}
                    </span>
                    <ChevronRight className="w-3.5 h-3.5" />
                  </button>
                )}
              </div>

              <p className="text-[10px] font-mono text-stone text-center">
                {language === "hi"
                  ? "साइट को सीधे आपके सक्रिय रूट प्लानर में जोड़ता है।"
                  : "Adds site directly to your active route builder in the navigation bar."}
              </p>
            </div>
          </div>
        </div>

        {/* 3. SUGGESTED HOTELS NEAR HERE STRIP */}
        {destination.nearbyHotels && destination.nearbyHotels.length > 0 && (
          <div className="mt-16 pt-10 border-t border-stone/30 space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-2 border-l-2 border-gold pl-3">
              <div>
                <span className="font-mono text-xs text-gold uppercase tracking-widest block">
                  {language === "hi"
                    ? "हेरिटेज स्टे निवास"
                    : "Heritage Stay Accommodations"}
                </span>
                <h3 className="font-display text-2xl text-charcoal font-bold">
                  {language === "hi"
                    ? `${getName(destination)} के निकटतम होटल`
                    : `Suggested Hotels Near ${getName(destination)}`}
                </h3>
              </div>
              <span className="font-mono text-xs text-stone">
                Toran TCGL Bungalows & Restored Haveli Stays
              </span>
            </div>

            {/* Horizontally Scrollable Row of Hotel Cards */}
            <div className="flex items-stretch gap-6 overflow-x-auto pb-4 scrollbar-none">
              {destination.nearbyHotels.map((hotel) => (
                <div
                  key={hotel.id}
                  className="bg-ink text-salt border border-stone/40 min-w-[280px] sm:min-w-[320px] max-w-[340px] flex-shrink-0 flex flex-col justify-between p-4 space-y-4 rounded-2xl shadow-md"
                >
                  <div className="relative h-40 overflow-hidden border border-stone/30 bg-charcoal rounded-xl">
                    <ImageWithFallback
                      src={hotel.imageUrl}
                      alt={hotel.name}
                      category="hotel"
                      className="w-full h-full object-cover hover:scale-105 transition-all duration-300 rounded-xl"
                    />

                    {/* Official Stay Type Badge */}
                    <span className="absolute top-2 left-2 bg-salt text-ink font-mono text-[10px] font-bold px-2 py-0.5 uppercase tracking-wider rounded-md">
                      {hotel.stayType}
                    </span>

                    {/* Rating Badge */}
                    <span className="absolute bottom-2 right-2 bg-ink/90 text-gold font-mono text-[10px] font-bold px-2 py-0.5 border border-gold/40 rounded-md">
                      {hotel.rating}
                    </span>
                  </div>

                  <div className="space-y-1">
                    <h4 className="font-display text-lg font-bold text-salt leading-tight">
                      {hotel.name}
                    </h4>
                    <p className="text-xs font-mono text-stone flex items-center gap-1">
                      <Hotel className="w-3.5 h-3.5 text-gold shrink-0" />
                      <span>{hotel.location}</span>
                    </p>
                  </div>

                  <div className="flex items-center justify-between pt-3 border-t border-stone/30 text-xs font-mono">
                    <span className="text-stone">
                      {language === "hi"
                        ? "किराया:"
                        : "Tariff:"}
                    </span>
                    <span className="text-gold font-bold">
                      {hotel.pricePerNight}
                    </span>
                  </div>

                  {onSelectPreferredHotel && (
                    <button
                      onClick={() =>
                        onSelectPreferredHotel(destination.id, hotel.id)
                      }
                      className={`w-full py-2 px-3 text-xs font-mono font-bold uppercase transition-all cursor-pointer flex items-center justify-center gap-1.5 border rounded-lg ${
                        preferredHotels?.[destination.id] === hotel.id
                          ? "bg-gold text-ink border-gold shadow-xs"
                          : "bg-salt/10 hover:bg-gold hover:text-ink text-salt border-stone/40"
                      }`}
                    >
                      {preferredHotels?.[destination.id] === hotel.id ? (
                        <>
                          <CheckCircle2 className="w-3.5 h-3.5 text-ink shrink-0" />
                          <span>
                            {language === "hi"
                              ? "चयनित स्थान"
                              : "Preferred Stay Selected"}
                          </span>
                        </>
                      ) : (
                        <span>
                          {language === "hi"
                            ? "पसंदीदा स्थान चुनें"
                            : "Set as Preferred Stay"}
                        </span>
                      )}
                    </button>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

frontend/src/components/ChevronDivider.t:
import React from "react";

interface ChevronDividerProps {
  className?: string;
  count?: number;
}

export const ChevronDivider: React.FC<ChevronDividerProps> = ({
  className = "",
  count = 8,
}) => {
  return (
    <div
      className={`flex items-center justify-center gap-1.5 py-4 ${className}`}
      aria-hidden="true"
    >
      {Array.from({ length: count }).map((_, idx) => (
        <svg
          key={idx}
          width="24"
          height="12"
          viewBox="0 0 24 12"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          className="text-gold/70"
        >
          <path
            d="M0 0L6 6L0 12H3.5L9.5 6L3.5 0H0ZM12 0L18 6L12 12H15.5L21.5 6L15.5 0H12Z"
            fill="currentColor"
          />
        </svg>
      ))}
    </div>
  );
};

frontend/src/components/BudgetPlannerVie:
import React, { useState, useMemo } from "react";
import { api, useApi } from "../api";
import { ItineraryConfig } from "./ItineraryView";
import { useLanguage } from "../context/LanguageContext";

import {
  DollarSign,
  ArrowLeft,
  AlertTriangle,
  Hotel,
  Car,
  Ticket,
  Utensils,
  ChevronRight,
  Sparkles,
  SlidersHorizontal,
  Printer,
  Share2,
  Check,
  TrendingDown,
  Info,
} from "lucide-react";

interface BudgetPlannerViewProps {
  config: ItineraryConfig | null;
  onBackToItinerary: () => void;
  onBackToPlanner: () => void;
  onSelectDestination?: (dest: import("../api/types").Destination) => void;
  onBudgetChange?: (budget: number) => void;
}

export const BudgetPlannerView: React.FC<BudgetPlannerViewProps> = ({
  config,
  onBackToItinerary,
  onBackToPlanner,
  onSelectDestination,
  onBudgetChange,
}) => {
  const { language, t, getName } = useLanguage();

  const activeConfig = config;
  const request = useApi(async signal => {
    const id = activeConfig?.tripId ?? "";
    const [budget, dto] = await Promise.all([api.budget(id, signal), api.trip(id, signal)]);
    const city = await api.destination(dto.trip.destination_id, signal);
    return {budget, dto, city};
  }, [activeConfig?.tripId]);
  const tripDays = request.data?.dto.trip.trip_days ?? 0;
  const travelCost = request.data?.budget.transit ?? 0;
  const hotelCost = request.data?.budget.hotel ?? 0;
  const entryCost = request.data?.budget.attractions ?? 0;
  const foodCost = request.data?.budget.meals ?? 0;
  const totalEstimatedCost = request.data?.budget.total ?? 0;
  const [simulatedBudget, setAllocatedBudget] = useState<number>(0);
  const allocatedBudget = request.data?.budget.budget ?? 0;
  const [budgetInputError, setBudgetInputError] = useState<string>("");

  const [appliedTips, setAppliedTips] = useState<string[]>([]);
  const [savedShareNotice, setSavedShareNotice] = useState<boolean>(false);

  // ── ASI discount: mathematically correct 10% of actual entry cost ──────────
  const effectiveTravelCost = travelCost;
  const effectiveHotelCost = hotelCost;
  const effectiveEntryCost = entryCost;
  const asiDiscount = 0;
  const currentEffectiveCost = totalEstimatedCost;

  const currentIsOver = currentEffectiveCost > allocatedBudget;
  const currentOverAmount = currentEffectiveCost - allocatedBudget;

  // Guard against zero/negative allocated budget to avoid nonsensical percentages
  const currentFillPercent =
    allocatedBudget > 0
      ? Math.min(100, Math.round((currentEffectiveCost / allocatedBudget) * 100))
      : 0;

  const handlePrint = () => window.print();

  const handleShare = async () => {
    try {
      if (navigator.share) {
        await navigator.share({
          title: "Gujarat Heritage Budget Ledger",
          text: `Financial breakdown for my ${tripDays}-day Gujarat Heritage trip: Total ₹${currentEffectiveCost.toLocaleString()}`,
          url: window.location.href,
        });
      } else {
        await navigator.clipboard.writeText(window.location.href);
        setSavedShareNotice(true);
        setTimeout(() => setSavedShareNotice(false), 3000);
      }
    } catch (error) {
      if ((error as Error).name !== "AbortError") {
        setBudgetInputError("Unable to share the budget. Copy the page address manually.");
      }
    }
  };

  const toggleTip = (_tipId: string) => {
    setBudgetInputError("The ledger shows saved costs. Change trip parameters in the planner to generate a new budget.");
  };
  const activeCity = request.data?.city;
  const cityName = activeCity ? getName(activeCity) : "";
  if(request.loading) return <p role="status">Loading saved trip budget...</p>;
  if(request.error || !request.data) return <p role="alert">{request.error || "Generate a trip first."} <button onClick={request.reload}>Retry</button> <button onClick={onBackToPlanner}>Open planner</button></p>;

  return (
    <div className="bg-salt min-h-screen py-8 px-4 sm:px-6 lg:px-8 border-b border-stone/30 animate-fadeIn selection:bg-gold selection:text-ink">
      <div className="max-w-6xl mx-auto space-y-8">
        {request.data.budget.transport_cost_known === false && <p role="status">Transport fares are unknown and excluded from this saved total.</p>}
        {/* Navigation Action Bar */}
        <div className="flex flex-wrap items-center justify-between gap-4 border-b border-stone/30 pb-4">
          <div className="flex items-center gap-3">
            <button
              onClick={onBackToItinerary}
              className="inline-flex items-center gap-2 bg-ink hover:bg-ink/90 text-salt border border-gold text-xs font-mono px-4 py-2 transition-colors cursor-pointer rounded-lg shadow-xs"
            >
              <ArrowLeft className="w-3.5 h-3.5 text-gold" />
              <span>
                {language === "hi"
                  ? "यात्रा प्लानर पर वापस जाएं"
                  : "Return to Itinerary View"}
              </span>
            </button>

            <button
              onClick={onBackToPlanner}
              className="inline-flex items-center gap-2 bg-stone/20 hover:bg-stone/30 text-charcoal border border-stone/40 text-xs font-mono px-4 py-2 transition-colors cursor-pointer rounded-lg"
            >
              <SlidersHorizontal className="w-3.5 h-3.5 text-ink" />
              <span>
                {language === "hi"
                  ? "मुख्य प्लानर में बदलाव करें"
                  : "Adjust Trip Parameters"}
              </span>
            </button>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={handleShare}
              className="inline-flex items-center gap-1.5 bg-salt border border-stone/40 hover:border-gold text-charcoal text-xs font-mono px-3 py-2 transition-colors cursor-pointer rounded-lg"
            >
              <Share2 className="w-3.5 h-3.5 text-gold" />
              <span>
                {language === "hi"
                  ? "शेयर करें"
                  : "Share Ledger"}
              </span>
            </button>

            <button
              onClick={handlePrint}
              className="inline-flex items-center gap-1.5 bg-salt border border-stone/40 hover:border-gold text-charcoal text-xs font-mono px-3 py-2 transition-colors cursor-pointer rounded-lg"
            >
              <Printer className="w-3.5 h-3.5 text-gold" />
              <span>
                {language === "hi"
                  ? "प्रिंट लेजर"
                  : "Print Ledger"}
              </span>
            </button>
          </div>
        </div>

        {savedShareNotice && (
          <div className="p-3 bg-emerald-900 text-salt border border-emerald-500 text-xs font-mono flex items-center gap-2 animate-fadeIn rounded-xl">
            <Check className="w-4 h-4 text-emerald-300" />
            <span>Budget ledger breakdown link copied to clipboard!</span>
          </div>
        )}

        {/* No active itinerary notice */}
        {!activeConfig && (
          <div className="p-4 bg-amber-50 border border-amber-400 text-amber-900 font-mono text-xs flex items-start gap-2.5 rounded-xl">
            <Info className="w-4 h-4 shrink-0 mt-0.5 text-amber-600" />
            <span>
              No active itinerary found. Generate a trip from the planner first
              to see your personalised budget breakdown.
            </span>
          </div>
        )}

        {/* ================= 1. HEADER: BUDGET VS ESTIMATED COST BAR ================= */}
        <div className="bg-ink text-salt p-6 sm:p-8 border-2 border-gold space-y-6 relative shadow-lg rounded-2xl">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-stone/30 pb-4">
            <div>
              <div className="flex items-center gap-2 font-mono text-[11px] uppercase tracking-widest text-gold mb-1">
                <DollarSign className="w-4 h-4 text-gold" />
                <span>Financial Monograph &amp; Circuit Audit</span>
              </div>
              <h1 className="font-display text-2xl sm:text-4xl text-salt font-bold">
                {cityName} Heritage Budget Ledger
              </h1>
              {activeConfig && (
                <p className="font-mono text-xs text-stone mt-1">
                  {tripDays}-day itinerary · {activeConfig.strategy || "distance-first"} strategy
                </p>
              )}
            </div>

            {/* Interactive Budget Adjustment Control */}
            <div className="bg-salt/10 border border-stone/40 p-3 space-y-1 font-mono text-xs rounded-xl">
              <span className="text-stone text-[10px] uppercase block tracking-wider">
                Simulate Target Budget Cap:
              </span>
              <div className="flex items-center gap-2">
                <span className="text-gold font-bold">₹</span>
                <input
                  type="number"
                  step="500"
                  min="0"
                  max="100000"
                  value={allocatedBudget}
                  onChange={(e) => {
                    const raw = Number(e.target.value);
                    if (isNaN(raw) || raw < 0) {
                      setBudgetInputError("Budget cannot be negative.");
                      setAllocatedBudget(0);
                      setBudgetInputError("Use Adjust Trip Parameters to save a new budget.");
                    } else {
                      setBudgetInputError("");
                      setAllocatedBudget(raw);
                      setBudgetInputError("Use Adjust Trip Parameters to save a new budget.");
                    }
                  }}
                  className="bg-salt text-ink font-mono font-bold text-base px-2 py-1 border border-gold outline-none w-28 rounded-md"
                />
                <span className="text-stone text-[10px]">INR</span>
              </div>
              {budgetInputError && (
                <p className="text-madder text-[10px] font-mono flex items-center gap-1 pt-1">
                  <AlertTriangle className="w-3 h-3 shrink-0" />
                  {budgetInputError}
                </p>
              )}
            </div>
          </div>

          {/* LEDGER BAR HEADER DISPLAY */}
          <div className="space-y-3 font-mono">
            <div className="flex flex-col sm:flex-row sm:items-end justify-between text-xs sm:text-sm gap-2">
              <div>
                <span className="text-stone text-[11px] uppercase tracking-wider block">
                  Allocated Budget Cap:
                </span>
                <span className="text-salt font-bold text-lg sm:text-xl">
                  ₹{allocatedBudget.toLocaleString("en-IN")}
                </span>
              </div>

              <div className="sm:text-right">
                <span className="text-stone text-[11px] uppercase tracking-wider block">
                  Estimated Total Cost:
                </span>
                <span
                  className={`font-bold text-lg sm:text-xl ${currentIsOver ? "text-madder" : "text-gold"}`}
                >
                  ₹{currentEffectiveCost.toLocaleString("en-IN")}
                </span>
              </div>
            </div>

            {/* HORIZONTAL PROGRESS BAR */}
            <div className="space-y-1">
              <div className="w-full h-3 bg-stone/40 border border-stone/60 overflow-hidden relative rounded-full">
                <div
                  style={{ width: `${currentFillPercent}%` }}
                  className={`h-full transition-all duration-500 rounded-full ${
                    currentIsOver ? "bg-madder" : "bg-gold"
                  }`}
                />
              </div>

              <div className="flex justify-between text-[10px] text-stone">
                <span>0%</span>
                <span>{allocatedBudget > 0 ? `${currentFillPercent}% Capacity` : "—"}</span>
                <span>100% (₹{allocatedBudget.toLocaleString("en-IN")})</span>
              </div>
            </div>

            {/* WARNING LINE BELOW IN ERROR VOICE IF OVER BUDGET */}
            {currentIsOver && allocatedBudget > 0 && (
              <div className="p-3 bg-madder/20 border-2 border-madder text-salt text-xs font-mono flex items-start gap-2.5 animate-fadeIn rounded-xl">
                <AlertTriangle className="w-4 h-4 text-madder shrink-0 mt-0.5" />
                <div className="space-y-0.5">
                  <span className="font-bold text-salt block">
                    This plan is ₹{currentOverAmount.toLocaleString("en-IN")} over
                    your budget.
                  </span>
                  <span className="text-stone text-[11px] block">
                    Adjust your selected hotel or trip duration in the planner.
                  </span>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* ================= 2. BREAKDOWN BY CATEGORY ================= */}
        <div className="bg-white border-2 border-stone/40 p-6 space-y-4 shadow-2xs rounded-2xl">
          <div className="border-b border-stone/30 pb-3 flex items-center justify-between">
            <div>
              <span className="font-mono text-xs text-gold uppercase tracking-widest block">
                Itemized Cost Distribution
              </span>
              <h2 className="font-display text-xl text-charcoal font-bold">
                Category Breakdown
              </h2>
            </div>
            <span className="font-mono text-xs text-stone">
              {activeConfig ? `${cityName} · ${tripDays} days` : "No active itinerary"}
            </span>
          </div>

          <div className="space-y-3 font-mono text-xs">
            {/* Travel */}
            <div className="flex items-center justify-between p-3 bg-salt border border-stone/20 rounded-xl">
              <div className="flex items-center gap-3">
                <Car className="w-4 h-4 text-gold shrink-0" />
                <div>
                  <span className="font-bold text-charcoal block">
                    Transit &amp; Transport
                  </span>
                  <span className="text-[10px] text-stone">
                    Ferry crossings &amp; road transit
                    {appliedTips.includes("transit") && (
                      <span className="ml-1 text-emerald-700 font-bold">
                        (−₹1,100 GSRTC saving applied)
                      </span>
                    )}
                  </span>
                </div>
              </div>
              <span className={`font-bold text-sm ${appliedTips.includes("transit") ? "text-emerald-700" : "text-charcoal"}`}>
                {request.data.budget.transport_cost_known === false ? "Unknown (excluded)" : `₹${effectiveTravelCost.toLocaleString("en-IN")}`}
                {appliedTips.includes("transit") && travelCost > 0 && (
                  <span className="block text-[10px] font-normal text-stone line-through">
                    ₹{travelCost.toLocaleString("en-IN")}
                  </span>
                )}
              </span>
            </div>

            {/* Hotel */}
            <div className="flex items-center justify-between p-3 bg-salt border border-stone/20 rounded-xl">
              <div className="flex items-center gap-3">
                <Hotel className="w-4 h-4 text-gold shrink-0" />
                <div>
                  <span className="font-bold text-charcoal block">
                    Heritage Stays &amp; Accommodation
                  </span>
                  <span className="text-[10px] text-stone">
                    {tripDays} night{tripDays !== 1 ? "s" : ""} at selected hotel
                    {appliedTips.includes("hotel") && (
                      <span className="ml-1 text-emerald-700 font-bold">
                        (−₹2,200 Toran saving applied)
                      </span>
                    )}
                  </span>
                </div>
              </div>
              <span className={`font-bold text-sm ${appliedTips.includes("hotel") ? "text-emerald-700" : "text-charcoal"}`}>
                ₹{effectiveHotelCost.toLocaleString("en-IN")}
                {appliedTips.includes("hotel") && (
                  <span className="block text-[10px] font-normal text-stone line-through">
                    ₹{hotelCost.toLocaleString("en-IN")}
                  </span>
                )}
              </span>
            </div>

            {/* Entry Tariffs */}
            <div className="flex items-center justify-between p-3 bg-salt border border-stone/20 rounded-xl">
              <div className="flex items-center gap-3">
                <Ticket className="w-4 h-4 text-gold shrink-0" />
                <div>
                  <span className="font-bold text-charcoal block">
                    ASI Monument Entry Tariffs
                  </span>
                  <span className="text-[10px] text-stone">
                    Attraction entry fees for {cityName}
                    {appliedTips.includes("pass") && asiDiscount > 0 && (
                      <span className="ml-1 text-emerald-700 font-bold">
                        (−₹{asiDiscount.toLocaleString("en-IN")} · 10% ASI discount)
                      </span>
                    )}
                  </span>
                </div>
              </div>
              <span className={`font-bold text-sm ${appliedTips.includes("pass") ? "text-emerald-700" : "text-charcoal"}`}>
                ₹{effectiveEntryCost.toLocaleString("en-IN")}
                {appliedTips.includes("pass") && asiDiscount > 0 && (
                  <span className="block text-[10px] font-normal text-stone line-through">
                    ₹{entryCost.toLocaleString("en-IN")}
                  </span>
                )}
              </span>
            </div>

            {/* Food */}
            <div className="flex items-center justify-between p-3 bg-salt border border-stone/20 rounded-xl">
              <div className="flex items-center gap-3">
                <Utensils className="w-4 h-4 text-gold shrink-0" />
                <div>
                  <span className="font-bold text-charcoal block">
                    Authentic Gujarati Thali &amp; Dining
                  </span>
                  <span className="text-[10px] text-stone">
                    Local culinary stops &amp; tea breaks
                  </span>
                </div>
              </div>
              <span className="font-bold text-charcoal text-sm">
                ₹{foodCost.toLocaleString("en-IN")}
              </span>
            </div>

            {/* Total row */}
            <div className="flex items-center justify-between p-3 bg-ink text-salt border border-gold rounded-xl">
              <span className="font-bold text-xs uppercase tracking-wider">
                Grand Total (persisted stops)
              </span>
              <span className="font-bold text-gold text-base">
                ₹{currentEffectiveCost.toLocaleString("en-IN")}
              </span>
            </div>
          </div>
        </div>

        {/* ================= 3. OPTIMIZATION TIPS ================= */}
        <div className="bg-ink text-salt p-6 border-2 border-gold space-y-4 rounded-2xl shadow-md">
          <div className="border-b border-stone/30 pb-3 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-gold" />
              <h3 className="font-display text-lg text-salt font-bold">
                Budget Optimization Strategy
              </h3>
            </div>
            <span className="font-mono text-xs text-gold font-bold">
              Tip Savings: Not available from the server
            </span>
          </div>

          <p className="text-xs font-mono text-stone">
            The server has no verified savings data for these options. Adjust trip
            parameters to generate a new persisted budget:
          </p>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 font-mono text-xs">
            {/* Tip 1 — Hotel Switch */}
            <button
              onClick={() => toggleTip("hotel")}
              className={`p-4 border text-left transition-all cursor-pointer space-y-2 rounded-xl ${
                appliedTips.includes("hotel")
                  ? "bg-gold text-ink border-gold font-bold shadow-md"
                  : "bg-salt/10 text-salt border-stone/40 hover:border-gold"
              }`}
            >
              <div className="flex items-center justify-between">
                <span className="text-[10px] uppercase tracking-wider text-stone">
                  Stay Saver
                </span>
                <span className="font-bold text-madder bg-salt px-1.5 py-0.5 text-[10px] rounded-md">
                  Savings not available
                </span>
              </div>
              <h4 className="font-display text-sm font-bold">
                Switch to Toran Guest House
              </h4>
              <p className="text-[11px] opacity-90 font-normal">
                Opt for Gujarat Tourism (TCGL) Toran guest houses over private
                heritage stays.
              </p>
              <div className="pt-1 text-[10px] font-bold uppercase flex items-center gap-1">
                {appliedTips.includes("hotel")
                  ? "✓ Applied to Ledger"
                  : "Review in planner"}
              </div>
            </button>

            {/* Tip 2 — ASI Pass (10% of actual entry cost) */}
            <button
              onClick={() => toggleTip("pass")}
              className={`p-4 border text-left transition-all cursor-pointer space-y-2 rounded-xl ${
                appliedTips.includes("pass")
                  ? "bg-gold text-ink border-gold font-bold shadow-md"
                  : "bg-salt/10 text-salt border-stone/40 hover:border-gold"
              }`}
            >
              <div className="flex items-center justify-between">
                <span className="text-[10px] uppercase tracking-wider text-stone">
                  ASI Tariff Pass
                </span>
                <span className="font-bold text-madder bg-salt px-1.5 py-0.5 text-[10px] rounded-md">
                  Savings not available
                </span>
              </div>
              <h4 className="font-display text-sm font-bold">
                Book Online ASI Combination Ticket
              </h4>
              <p className="text-[11px] opacity-90 font-normal">
                No verified combination-ticket price is available for this trip.
              </p>
              <div className="pt-1 text-[10px] font-bold uppercase flex items-center gap-1">
                {appliedTips.includes("pass")
                  ? "✓ Applied to Ledger"
                  : "Review in planner"}
              </div>
            </button>

            {/* Tip 3 — GSRTC Transit */}
            <button
              onClick={() => toggleTip("transit")}
              className={`p-4 border text-left transition-all cursor-pointer space-y-2 rounded-xl ${
                appliedTips.includes("transit")
                  ? "bg-gold text-ink border-gold font-bold shadow-md"
                  : "bg-salt/10 text-salt border-stone/40 hover:border-gold"
              }`}
            >
              <div className="flex items-center justify-between">
                <span className="text-[10px] uppercase tracking-wider text-stone">
                  GSRTC Express Transit
                </span>
                <span className="font-bold text-madder bg-salt px-1.5 py-0.5 text-[10px] rounded-md">
                  Savings not available
                </span>
              </div>
              <h4 className="font-display text-sm font-bold">
                GSRTC Volvo Bus for Inter-City Legs
              </h4>
              <p className="text-[11px] opacity-90 font-normal">
                Use GSRTC Volvo AC coach between Ahmedabad, Mehsana, and
                Vadodara instead of private cab hire.
              </p>
              <div className="pt-1 text-[10px] font-bold uppercase flex items-center gap-1">
                {appliedTips.includes("transit")
                  ? "✓ Applied to Ledger"
                  : "Review in planner"}
              </div>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

frontend/src/components/BestTimeNote.tsx:
import React, { useState } from "react";
import { Clock } from "lucide-react";

interface BestTimeNoteProps {
  note?: string;
  className?: string;
}

export const BestTimeNote: React.FC<BestTimeNoteProps> = ({
  note,
  className = "",
}) => {
  const [isExpanded, setIsExpanded] = useState<boolean>(false);

  if (!note) return null;

  return (
    <div
      onClick={(e) => {
        e.stopPropagation();
        setIsExpanded((prev) => !prev);
      }}
      title={`${note} (click to toggle full text)`}
      className={`group cursor-pointer inline-flex items-center gap-1.5 text-xs text-stone font-body italic transition-colors hover:text-charcoal ${className}`}
    >
      <Clock className="w-3.5 h-3.5 text-gold shrink-0" />
      <span
        className={`font-sans italic transition-all ${
          isExpanded
            ? "whitespace-normal block break-words"
            : "truncate line-clamp-1"
        }`}
      >
        {note}
      </span>
    </div>
  );
};

frontend/src/components/AuthView.tsx:
import { api, errorMessage } from "../api";
import React, { useState, useRef } from "react";
import {
  Compass,
  Route,
  ArrowLeft,
  AlertCircle,
  CheckCircle2,
  Lock,
  Mail,
  User,
  Eye,
  EyeOff,
} from "lucide-react";
import { useLanguage } from "../context/LanguageContext";

interface AuthViewProps {
  initialMode?: "login" | "register";
  onCloseOrGuest: () => void;
  onAuthSuccess?: (user: {
    name: string;
    email: string;
    role: "tourist" | "operator";
  }) => void;
}

export const AuthView: React.FC<AuthViewProps> = ({
  initialMode = "login",
  onCloseOrGuest,
  onAuthSuccess,
}) => {
  const { t } = useLanguage();
  const [mode, setMode] = useState<"login" | "register">(initialMode);

  // Form Fields
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [role, setRole] = useState<"tourist" | "operator">("tourist");

  // Password Visibility
  const [showPassword, setShowPassword] = useState(false);

  // Error States
  const [emailError, setEmailError] = useState("");
  const [passwordError, setPasswordError] = useState("");
  const [nameError, setNameError] = useState("");
  const [confirmPasswordError, setConfirmPasswordError] = useState("");
  const [formGeneralError, setFormGeneralError] = useState("");

  const [pending, setPending] = useState(false);
  const pendingRef = useRef(false);
  // Server-confirmed authentication
  const [successMsg, setSuccessMsg] = useState("");
  // Password recovery availability
  const [showRecoveryNotice, setShowRecoveryNotice] = useState(false);

  const validateEmail = (val: string) => {
    if (!val.trim()) {
      return "An email address is required. Please enter your email.";
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(val)) {
      return "That email format is invalid. Ensure it includes an @ symbol and a domain name (e.g. name@example.com).";
    }
    return "";
  };

  const validatePassword = (val: string) => {
    if (!val) {
      return "Password cannot be blank. Enter your account password.";
    }
    if (val.length < 6) {
      return "Password must be at least 6 characters long. Add more characters to proceed.";
    }
    return "";
  };

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (pendingRef.current) return;
    setFormGeneralError(""); setSuccessMsg("");
    const eErr = validateEmail(email);
    setEmailError(eErr);
    if(eErr) return;
    pendingRef.current = true; setPending(true);
    try {
      const user = await api.login(email, password);
      setSuccessMsg("Signed in successfully.");
      onAuthSuccess?.(user);
    } catch(error) { setFormGeneralError(errorMessage(error)); }
    finally { pendingRef.current = false; setPending(false); }
  };
  const handleRegisterSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if(pendingRef.current) return;
    setFormGeneralError(""); setSuccessMsg("");
    if(password !== confirmPassword) { setConfirmPasswordError("Passwords do not match."); return; }
    setConfirmPasswordError(""); pendingRef.current = true; setPending(true);
    try {
      await api.register(name, email, password, role);
      setSuccessMsg("Account created. Sign in with your new credentials.");
      setMode("login"); setPassword(""); setConfirmPassword("");
    } catch(error) { setFormGeneralError(errorMessage(error)); }
    finally { pendingRef.current = false; setPending(false); }
  };

  return (
    <div
      id="account"
      className="min-h-[85vh] flex items-center justify-center p-4 sm:p-6 bg-salt my-6"
    >
      <div className="w-full max-w-5xl bg-salt border-2 border-stone/40 shadow-2xl overflow-hidden grid grid-cols-1 md:grid-cols-12 relative rounded-2xl">
        {pending && <p role="status">Contacting authentication server...</p>}
        {/* LEFT COLUMN: Ink Indigo Banner */}
        <div className="md:col-span-5 bg-ink text-salt p-8 lg:p-12 flex flex-col justify-between relative overflow-hidden min-h-[260px] md:min-h-[580px]">
          <div
            className="absolute inset-0 bg-stepwell-pattern opacity-25 pointer-events-none"
            aria-hidden="true"
          />

          <div className="relative z-10 space-y-4">
            <button
              onClick={onCloseOrGuest}
              className="inline-flex items-center gap-2 text-xs font-mono text-stone hover:text-gold transition-colors py-1 px-2 border border-stone/30 bg-ink/80 cursor-pointer rounded-lg shadow-xs"
            >
              <ArrowLeft className="w-3.5 h-3.5 text-gold" />
              <span>Back to Destinations</span>
            </button>

            <div className="flex items-center gap-2.5 pt-4">
              <div className="w-7 h-7 border border-gold flex items-center justify-center p-0.5 bg-ink">
                <div className="w-full h-full bg-gold/90"></div>
              </div>
              <span className="font-display text-lg text-salt tracking-tight">
                Heritage Tourism Planner
              </span>
            </div>
          </div>

          <div className="relative z-10 my-8 space-y-3">
            <span className="font-mono text-xs text-gold uppercase tracking-widest block">
              {mode === "login"
                ? "Gujarat Route Ledger Access"
                : "Join The Heritage Network"}
            </span>
            <h2 className="font-display text-2xl sm:text-3xl lg:text-4xl text-salt leading-tight">
              {mode === "login"
                ? "Your Gujarat itinerary, ready in minutes."
                : "Plan terrace routes or present heritage stays."}
            </h2>
            <p className="text-xs font-body text-stone leading-relaxed max-w-xs">
              Access verified ticket prices, distance ledgers, and direct
              contact details for master craftspeople across Kutch, Modhera, and
              Saurashtra.
            </p>
          </div>

          <div className="relative z-10 pt-4 border-t border-stone/30 flex items-center justify-between text-[11px] font-mono text-stone">
            <span>Stepwell System v2.4</span>
            <span className="text-gold">Server Account Session</span>
          </div>
        </div>

        {/* RIGHT COLUMN: Salt White Form */}
        <div className="md:col-span-7 bg-salt text-charcoal p-6 sm:p-10 lg:p-12 flex flex-col justify-between">
          <div>
            <div className="flex items-center justify-between border-b border-stone/30 pb-4 mb-8">
              <div className="flex items-center gap-6">
                <button
                  type="button"
                  onClick={() => {
                    setMode("login");
                    setEmailError("");
                    setPasswordError("");
                    setFormGeneralError("");
                  }}
                  className={`font-display text-xl sm:text-2xl transition-colors cursor-pointer ${
                    mode === "login"
                      ? "text-ink font-semibold border-b-2 border-gold pb-1 -mb-[18px]"
                      : "text-stone hover:text-charcoal"
                  }`}
                >
                  {t("nav.login", "Log In")}
                </button>

                <button
                  type="button"
                  onClick={() => {
                    setMode("register");
                    setEmailError("");
                    setPasswordError("");
                    setFormGeneralError("");
                  }}
                  className={`font-display text-xl sm:text-2xl transition-colors cursor-pointer ${
                    mode === "register"
                      ? "text-ink font-semibold border-b-2 border-gold pb-1 -mb-[18px]"
                      : "text-stone hover:text-charcoal"
                  }`}
                >
                  {t("auth.register", "Register")}
                </button>
              </div>

              <button
                type="button"
                onClick={onCloseOrGuest}
                className="text-xs font-mono text-stone hover:text-ink underline transition-colors cursor-pointer"
              >
                Continue as guest
              </button>
            </div>

            {successMsg && (
              <div className="mb-6 p-4 bg-ink text-salt border-2 border-gold font-mono text-xs flex items-center gap-3 rounded-xl">
                <CheckCircle2 className="w-5 h-5 text-gold shrink-0" />
                <span>{successMsg}</span>
              </div>
            )}

            {formGeneralError && (
              <div className="mb-6 p-4 bg-madder/10 border-l-4 border-madder text-madder font-mono text-xs flex items-center gap-2 rounded-xl">
                <AlertCircle className="w-4 h-4 shrink-0" />
                <span>{formGeneralError}</span>
              </div>
            )}

            {mode === "login" ? (
              <form
                onSubmit={handleLoginSubmit}
                className="space-y-6"
                noValidate
              >
                <div className="space-y-1.5">
                  <label
                    htmlFor="login-email"
                    className="block text-xs font-mono text-charcoal font-medium uppercase tracking-wider"
                  >
                    {t("auth.email", "Email Address")}
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-stone">
                      <Mail className="w-4 h-4" />
                    </div>
                    <input
                      id="login-email"
                      type="email"
                      value={email}
                      onChange={(e) => {
                        setEmail(e.target.value);
                        if (emailError) setEmailError("");
                      }}
                      placeholder="e.g. traveler@heritage.in"
                      className={`w-full pl-10 pr-3 py-3 text-sm bg-salt border font-body transition-colors focus:outline-none focus:border-gold focus:ring-1 focus:ring-gold rounded-lg ${
                        emailError
                          ? "border-madder bg-madder/5"
                          : "border-stone/50 hover:border-stone"
                      }`}
                      required
                    />
                  </div>
                  {emailError && (
                    <p className="text-xs font-mono text-madder flex items-start gap-1 pt-1">
                      <AlertCircle className="w-3.5 h-3.5 shrink-0 mt-0.5" />
                      <span>{emailError}</span>
                    </p>
                  )}
                </div>

                {showRecoveryNotice && (
                  <div className="bg-salt border-2 border-gold/60 p-3.5 mb-2 text-xs font-body animate-fadeIn rounded-xl">
                    <div className="flex items-center justify-between mb-1.5">
                      <div className="flex items-center gap-2">
                        <span className="bg-gold/20 text-gold border border-gold/40 px-1.5 py-0.5 text-[10px] font-mono font-bold uppercase tracking-wider rounded-md">
                          Password Reset Unavailable
                        </span>
                        <span className="font-mono text-charcoal font-semibold text-[11px]">
                          Password Recovery
                        </span>
                      </div>
                      <button
                        type="button"
                        onClick={() => setShowRecoveryNotice(false)}
                        className="text-stone hover:text-charcoal text-xs font-mono cursor-pointer p-0.5 rounded-md"
                        aria-label="Dismiss notice"
                      >
                        ✕
                      </button>
                    </div>
                    <p className="text-charcoal/80 text-[11px] leading-relaxed mb-1.5">
                      Accounts use <strong>server authentication</strong>. A password-reset endpoint and email delivery service are not available.
                    </p>
                    <p className="text-stone text-[10px] font-mono">
                      Your sign-in token is held in <code className="text-gold">sessionStorage</code>. Sign in with a registered email and password.
                    </p>
                  </div>
                )}

                <div className="space-y-1.5">
                  <div className="flex items-center justify-between">
                    <label
                      htmlFor="login-password"
                      className="block text-xs font-mono text-charcoal font-medium uppercase tracking-wider"
                    >
                      {t("auth.password", "Password")}
                    </label>
                    <button
                      type="button"
                      onClick={() => setShowRecoveryNotice(true)}
                      className="text-xs font-mono text-stone hover:text-gold transition-colors cursor-pointer"
                    >
                      Forgot password?
                    </button>
                  </div>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-stone">
                      <Lock className="w-4 h-4" />
                    </div>
                    <input
                      id="login-password"
                      type={showPassword ? "text" : "password"}
                      value={password}
                      onChange={(e) => {
                        setPassword(e.target.value);
                        if (passwordError) setPasswordError("");
                      }}
                      placeholder="••••••••••••"
                      className={`w-full pl-10 pr-10 py-3 text-sm bg-salt border font-body transition-colors focus:outline-none focus:border-gold focus:ring-1 focus:ring-gold rounded-lg ${
                        passwordError
                          ? "border-madder bg-madder/5"
                          : "border-stone/50 hover:border-stone"
                      }`}
                      required
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute inset-y-0 right-0 pr-3 flex items-center text-stone hover:text-charcoal cursor-pointer"
                      aria-label={
                        showPassword ? "Hide password" : "Show password"
                      }
                    >
                      {showPassword ? (
                        <EyeOff className="w-4 h-4" />
                      ) : (
                        <Eye className="w-4 h-4" />
                      )}
                    </button>
                  </div>
                  {passwordError && (
                    <p className="text-xs font-mono text-madder flex items-start gap-1 pt-1">
                      <AlertCircle className="w-3.5 h-3.5 shrink-0 mt-0.5" />
                      <span>{passwordError}</span>
                    </p>
                  )}
                </div>

                <button
                  type="submit" disabled={pending}
                  className="w-full bg-madder hover:bg-madder/90 text-salt py-3.5 px-6 font-mono text-xs uppercase tracking-wider font-semibold transition-colors shadow-sm border border-madder cursor-pointer rounded-lg"
                >
                  {t("nav.login", "Log In")}
                </button>

                <div className="text-center pt-2 text-xs font-body text-stone">
                  Need a new account?{" "}
                  <button
                    type="button"
                    onClick={() => {
                      setMode("register");
                      setEmailError("");
                      setPasswordError("");
                    }}
                    className="font-medium text-ink hover:text-gold underline cursor-pointer"
                  >
                    Register here
                  </button>
                </div>
              </form>
            ) : (
              <form
                onSubmit={handleRegisterSubmit}
                className="space-y-5"
                noValidate
              >
                <div className="space-y-2">
                  <label className="block text-xs font-mono text-charcoal font-medium uppercase tracking-wider">
                    Select Account Role:
                  </label>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <button
                      type="button"
                      onClick={() => setRole("tourist")}
                      className={`p-3.5 text-left border transition-all cursor-pointer flex flex-col justify-between rounded-xl ${
                        role === "tourist"
                          ? "border-gold bg-ink text-salt shadow-sm"
                          : "border-stone/40 bg-salt text-charcoal hover:border-stone"
                      }`}
                    >
                      <div className="flex items-center gap-2 mb-1">
                        <Compass
                          className={`w-4 h-4 ${role === "tourist" ? "text-gold" : "text-stone"}`}
                        />
                        <span className="font-display font-semibold text-sm">
                          Tourist
                        </span>
                      </div>
                      <p
                        className={`text-[11px] font-body leading-tight ${role === "tourist" ? "text-salt/80" : "text-stone"}`}
                      >
                        Plan custom terrace routes, save itineraries & access
                        craft guides.
                      </p>
                    </button>

                    <button
                      type="button"
                      onClick={() => setRole("operator")}
                      className={`p-3.5 text-left border transition-all cursor-pointer flex flex-col justify-between rounded-xl ${
                        role === "operator"
                          ? "border-gold bg-ink text-salt shadow-sm"
                          : "border-stone/40 bg-salt text-charcoal hover:border-stone"
                      }`}
                    >
                      <div className="flex items-center gap-2 mb-1">
                        <Route
                          className={`w-4 h-4 ${role === "operator" ? "text-gold" : "text-stone"}`}
                        />
                        <span className="font-display font-semibold text-sm">
                          Tour operator
                        </span>
                      </div>
                      <p
                        className={`text-[11px] font-body leading-tight ${role === "operator" ? "text-salt/80" : "text-stone"}`}
                      >
                        List heritage stays, guided stepwell tours & manage
                        bookings.
                      </p>
                    </button>
                  </div>
                </div>

                <div className="space-y-1">
                  <label
                    htmlFor="reg-name"
                    className="block text-xs font-mono text-charcoal font-medium uppercase tracking-wider"
                  >
                    Full Name
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-stone">
                      <User className="w-4 h-4" />
                    </div>
                    <input
                      id="reg-name"
                      type="text"
                      value={name}
                      onChange={(e) => {
                        setName(e.target.value);
                        if (nameError) setNameError("");
                      }}
                      placeholder="e.g. Vikramaditya Solanki"
                      className={`w-full pl-10 pr-3 py-2.5 text-sm bg-salt border font-body transition-colors focus:outline-none focus:border-gold focus:ring-1 focus:ring-gold rounded-lg ${
                        nameError
                          ? "border-madder bg-madder/5"
                          : "border-stone/50 hover:border-stone"
                      }`}
                      required
                    />
                  </div>
                  {nameError && (
                    <p className="text-xs font-mono text-madder flex items-start gap-1 pt-0.5">
                      <AlertCircle className="w-3.5 h-3.5 shrink-0 mt-0.5" />
                      <span>{nameError}</span>
                    </p>
                  )}
                </div>

                <div className="space-y-1">
                  <label
                    htmlFor="reg-email"
                    className="block text-xs font-mono text-charcoal font-medium uppercase tracking-wider"
                  >
                    {t("auth.email", "Email Address")}
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-stone">
                      <Mail className="w-4 h-4" />
                    </div>
                    <input
                      id="reg-email"
                      type="email"
                      value={email}
                      onChange={(e) => {
                        setEmail(e.target.value);
                        if (emailError) setEmailError("");
                      }}
                      placeholder="name@domain.com"
                      className={`w-full pl-10 pr-3 py-2.5 text-sm bg-salt border font-body transition-colors focus:outline-none focus:border-gold focus:ring-1 focus:ring-gold rounded-lg ${
                        emailError
                          ? "border-madder bg-madder/5"
                          : "border-stone/50 hover:border-stone"
                      }`}
                      required
                    />
                  </div>
                  {emailError && (
                    <p className="text-xs font-mono text-madder flex items-start gap-1 pt-0.5">
                      <AlertCircle className="w-3.5 h-3.5 shrink-0 mt-0.5" />
                      <span>{emailError}</span>
                    </p>
                  )}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <label
                      htmlFor="reg-password"
                      className="block text-xs font-mono text-charcoal font-medium uppercase tracking-wider"
                    >
                      {t("auth.password", "Password")}
                    </label>
                    <input
                      id="reg-password"
                      type="password"
                      value={password}
                      onChange={(e) => {
                        setPassword(e.target.value);
                        if (passwordError) setPasswordError("");
                      }}
                      placeholder="12+ chars, uppercase, lowercase, number, symbol"
                      className={`w-full px-3 py-2.5 text-sm bg-salt border font-body transition-colors focus:outline-none focus:border-gold focus:ring-1 focus:ring-gold rounded-lg ${
                        passwordError
                          ? "border-madder bg-madder/5"
                          : "border-stone/50 hover:border-stone"
                      }`}
                      required
                    />
                    {passwordError && (
                      <p className="text-[11px] font-mono text-madder pt-0.5">
                        {passwordError}
                      </p>
                    )}
                  </div>

                  <div className="space-y-1">
                    <label
                      htmlFor="reg-confirm"
                      className="block text-xs font-mono text-charcoal font-medium uppercase tracking-wider"
                    >
                      Confirm Password
                    </label>
                    <input
                      id="reg-confirm"
                      type="password"
                      value={confirmPassword}
                      onChange={(e) => {
                        setConfirmPassword(e.target.value);
                        if (confirmPasswordError) setConfirmPasswordError("");
                      }}
                      placeholder="Repeat password"
                      className={`w-full px-3 py-2.5 text-sm bg-salt border font-body transition-colors focus:outline-none focus:border-gold focus:ring-1 focus:ring-gold rounded-lg ${
                        confirmPasswordError
                          ? "border-madder bg-madder/5"
                          : "border-stone/50 hover:border-stone"
                      }`}
                      required
                    />
                    {confirmPasswordError && (
                      <p className="text-[11px] font-mono text-madder pt-0.5">
                        {confirmPasswordError}
                      </p>
                    )}
                  </div>
                </div>

                <button
                  type="submit" disabled={pending}
                  className="w-full bg-madder hover:bg-madder/90 text-salt py-3.5 px-6 font-mono text-xs uppercase tracking-wider font-semibold transition-colors shadow-sm border border-madder cursor-pointer rounded-lg"
                >
                  {t("auth.register", "Register")}
                </button>

                <div className="text-center pt-1 text-xs font-body text-stone">
                  Already registered?{" "}
                  <button
                    type="button"
                    onClick={() => {
                      setMode("login");
                      setEmailError("");
                      setPasswordError("");
                    }}
                    className="font-medium text-ink hover:text-gold underline cursor-pointer"
                  >
                    Log in here
                  </button>
                </div>
              </form>
            )}
          </div>

          <div className="pt-6 mt-6 border-t border-stone/30 text-center">
            <button
              type="button"
              onClick={onCloseOrGuest}
              className="text-xs font-mono text-stone hover:text-charcoal transition-colors cursor-pointer"
            >
              Continue as guest →
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

frontend/src/components/AlgorithmStatsPa:
import { displayNumber } from "../api";
import React, { useState } from "react";
import type { AlgorithmStats } from "../utils/itineraryPlanner";
import {
  Cpu,
  ChevronDown,
  ChevronUp,
  Zap,
  MapPin,
  Route,
  Layers,
  Clock,
} from "lucide-react";

export interface AlgorithmStatsPanelProps {
  stats: AlgorithmStats;
  collapsible?: boolean;
  defaultExpanded?: boolean;
  title?: string;
  className?: string;
}

export const AlgorithmStatsPanel: React.FC<AlgorithmStatsPanelProps> = ({
  stats,
  collapsible = true,
  defaultExpanded = false,
  title = "Algorithm Execution Stats",
  className = "",
}) => {
  const [isExpanded, setIsExpanded] = useState<boolean>(defaultExpanded);

  const summaryText = `Generated in ${displayNumber(stats.executionTimeMs)}ms -- ${stats.attractionsVisited} attractions, ${stats.directRoadConnectionsUsed} direct routes, ${stats.dijkstraFallbackCalls} Dijkstra fallbacks.`;

  return (
    <div
      className={`bg-ink text-salt border border-gold/40 shadow-sm transition-all ${className}`}
      id="algorithm-stats-panel"
    >
      {/* Strip Header / Summary Bar */}
      <div className="p-2.5 sm:p-3 flex items-center justify-between gap-3 flex-wrap sm:flex-nowrap">
        <div className="flex items-center gap-2.5 min-w-0">
          <div className="p-1 bg-gold/20 border border-gold/50 rounded-xs shrink-0">
            <Cpu className="w-3.5 h-3.5 text-gold" />
          </div>

          <div className="flex flex-col sm:flex-row sm:items-center gap-1 sm:gap-3 min-w-0">
            <span className="font-mono text-xs font-bold text-gold uppercase tracking-wider shrink-0">
              {title}
            </span>

            {collapsible && !isExpanded && (
              <span className="font-mono text-xs text-stone truncate max-w-full sm:max-w-md">
                Generated in{" "}
                <strong className="font-mono text-salt font-bold">
                  {displayNumber(stats.executionTimeMs)}ms
                </strong>{" "}
                --{" "}
                <strong className="font-mono text-salt font-bold">
                  {stats.attractionsVisited}
                </strong>{" "}
                attractions,{" "}
                <strong className="font-mono text-salt font-bold">
                  {stats.directRoadConnectionsUsed}
                </strong>{" "}
                direct routes,{" "}
                <strong className="font-mono text-salt font-bold">
                  {stats.dijkstraFallbackCalls}
                </strong>{" "}
                Dijkstra fallbacks.
              </span>
            )}
          </div>
        </div>

        {collapsible && (
          <button
            type="button"
            onClick={() => setIsExpanded(!isExpanded)}
            className="font-mono text-xs font-bold text-gold hover:text-salt bg-gold/10 hover:bg-gold/20 border border-gold/40 px-2.5 py-1 flex items-center gap-1 transition-colors cursor-pointer shrink-0 ml-auto"
            aria-expanded={isExpanded}
            aria-label="Toggle algorithm stats detail"
          >
            <span>
              {isExpanded ? "Hide algorithm stats" : "View algorithm stats"}
            </span>
            {isExpanded ? (
              <ChevronUp className="w-3.5 h-3.5 text-gold" />
            ) : (
              <ChevronDown className="w-3.5 h-3.5 text-gold" />
            )}
          </button>
        )}
      </div>

      {/* Expanded Detail Panel */}
      {(!collapsible || isExpanded) && (
        <div className="p-3 border-t border-gold/30 bg-ink/90 grid grid-cols-2 sm:grid-cols-4 gap-2.5 font-mono text-xs animate-fadeIn">
          {/* 1. Generation Time */}
          <div className="bg-salt/10 p-2 border border-stone/30 flex flex-col justify-between">
            <span className="text-[10px] text-gold uppercase tracking-wider block font-bold mb-1 flex items-center gap-1">
              <Clock className="w-3 h-3 text-gold" />
              Exec Time
            </span>
            <span className="font-mono font-bold text-salt text-sm">
              {displayNumber(stats.executionTimeMs)} ms
            </span>
          </div>

          {/* 2. Attractions Selection */}
          <div className="bg-salt/10 p-2 border border-stone/30 flex flex-col justify-between">
            <span className="text-[10px] text-gold uppercase tracking-wider block font-bold mb-1 flex items-center gap-1">
              <MapPin className="w-3 h-3 text-gold" />
              Attractions
            </span>
            <span className="font-mono font-bold text-salt text-sm">
              {stats.attractionsVisited}{" "}
              <span className="text-stone font-normal text-xs">
                / {stats.attractionsConsidered}
              </span>
            </span>
            <span className="text-[9px] text-stone">Selected by Greedy</span>
          </div>

          {/* 3. Direct Routes vs Dijkstra */}
          <div className="bg-salt/10 p-2 border border-stone/30 flex flex-col justify-between">
            <span className="text-[10px] text-gold uppercase tracking-wider block font-bold mb-1 flex items-center gap-1">
              <Route className="w-3 h-3 text-gold" />
              Connections
            </span>
            <span className="font-mono font-bold text-salt text-sm">
              {stats.directRoadConnectionsUsed}{" "}
              <span className="text-stone font-normal text-xs">dir</span> •{" "}
              {stats.dijkstraFallbackCalls}{" "}
              <span className="text-stone font-normal text-xs">Dijkstra</span>
            </span>
            <span className="text-[9px] text-stone">Direct vs Fallbacks</span>
          </div>

          {/* 4. Graph Operations */}
          <div className="bg-salt/10 p-2 border border-stone/30 flex flex-col justify-between">
            <span className="text-[10px] text-gold uppercase tracking-wider block font-bold mb-1 flex items-center gap-1">
              <Layers className="w-3 h-3 text-gold" />
              Graph Ops
            </span>
            <span className="font-mono font-bold text-salt text-sm">
              {displayNumber(stats.nodesVisited)}{" "}
              <span className="text-stone font-normal text-xs">nodes</span> /{" "}
              {displayNumber(stats.edgesRelaxed)}{" "}
              <span className="text-stone font-normal text-xs">edges</span>
            </span>
            <span className="text-[9px] text-stone">Visited & Relaxed</span>
          </div>
        </div>
      )}
    </div>
  );
};

frontend/src/components/AdminDashboardVi:
import React, { useState, useEffect, useRef } from "react";
import { api, useApi, errorMessage } from "../api";
import { HotelData } from "./HotelsView";
import { useLanguage } from "../context/LanguageContext";

import {
  Building2,
  MapPin,
  Compass,
  Plus,
  Edit2,
  Trash2,
  X,
  Check,
  AlertCircle,
  SlidersHorizontal,
  ChevronRight,
  Sparkles,
  Info,
  ArrowLeft,
  CheckCircle2,
  Layers,
  Utensils,
} from "lucide-react";

export interface AdminDestinationItem {
  id: string;
  name: string;
  district: string;
  category:
    | "UNESCO World Heritage Site"
    | "Heritage Sites"
    | "Religious Sites"
    | "Beaches"
    | "Wildlife & National Parks"
    | "Hill Stations & Ecotourism";
  estimatedCost: number;
  rating: number;
  lastUpdated: string;
}

export interface AdminHotelItem {
  id: string;
  name: string;
  destinationId: string;
  district: string;
  stayType: "Toran Hotel" | "Heritage Hotel" | "Registered Hotel" | "Homestay";
  pricePerNight: number;
  rating: number;
  lastUpdated: string;
}

export interface AdminAttractionItem {
  id: string;
  name: string;
  destinationName: string;
  district: string;
  category: string;
  rating: number;
  visitDurationHours: number;
  lat: number;
  lng: number;
  entryFee: string;
  lastUpdated: string;
}

export interface AdminRestaurantItem {
  id: string;
  name: string;
  city: string;
  location: string;
  rating: number;
  avgCostPerPerson: number;
  cuisine: string;
  lastUpdated: string;
}

export const CATEGORY_TAXONOMY = [
  "UNESCO World Heritage Site",
  "Heritage Sites",
  "Religious Sites",
  "Beaches",
  "Wildlife & National Parks",
  "Hill Stations & Ecotourism",
] as const;

export const STAY_TYPE_TAXONOMY = [
  "Toran Hotel",
  "Heritage Hotel",
  "Registered Hotel",
  "Homestay",
] as const;

interface AdminDashboardViewProps {
  onBackToProfile?: () => void;
}

export const AdminDashboardView: React.FC<AdminDashboardViewProps> = ({
  onBackToProfile,
}) => {
  const { t } = useLanguage();
  const [activeTab, setActiveTab] = useState<
    "destinations" | "hotels" | "attractions" | "restaurants"
  >("destinations");

  const request = useApi(async signal => {
    const [destinations, hotels, attractions, restaurants] = await Promise.all(
      ["destinations", "hotels", "attractions", "restaurants"].map(resource => api.adminList(resource, signal)));
    const city = (id: string) => destinations.find(d => d.id === id);
    return {
      destinations: destinations.map(d => ({...d,category:d.official_category ?? d.category ?? "",estimatedCost:d.entry_fee_numeric == null ? null : Number(d.entry_fee_numeric),rating:d.rating == null ? null : Number(d.rating),lastUpdated:"Not available"})),
      hotels: hotels.map(h => ({...h,destinationId:h.destination_id,district:city(h.destination_id)?.district ?? "",stayType:h.stay_type,pricePerNight:h.price_per_night,rating:h.rating == null ? null : Number(h.rating),lastUpdated:"Not available"})),
      attractions: attractions.map(a => ({...a,destinationId:a.destination_id,destinationName:city(a.destination_id)?.name ?? "",district:city(a.destination_id)?.district ?? "",visitDurationHours:Number(a.duration_hours),rating:a.rating == null ? null : Number(a.rating),entryFee:a.entry_fee ?? "",entryFeeNumeric:a.entry_fee_numeric == null ? null : Number(a.entry_fee_numeric),lat:Number(a.lat),lng:Number(a.lng),lastUpdated:"Not available"})),
      restaurants: restaurants.map(r => ({...r,destinationId:r.destination_id,city:city(r.destination_id)?.name ?? "",rating:r.rating == null ? null : Number(r.rating),avgCostPerPerson:r.avg_cost_per_person,lastUpdated:"Not available"})),
    };
  }, ["admin"]);
  const destinations = request.data?.destinations ?? [];
  const hotels = request.data?.hotels ?? [];
  const attractions = request.data?.attractions ?? [];
  const restaurants = request.data?.restaurants ?? [];
  const [pending, setPending] = useState(false);
  const [requestError, setRequestError] = useState("");
  const [isDrawerOpen, setIsDrawerOpen] = useState<boolean>(false);
  const [editingItem, setEditingItem] = useState<{
    type: "destinations" | "hotels" | "attractions" | "restaurants";
    id?: string;
    data: any;
  } | null>(null);

  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [formError, setFormError] = useState<string | null>(null);
  const openedFromProfile = useRef(false);
  useEffect(() => {
    if (!request.data || openedFromProfile.current) return;
    openedFromProfile.current = true;
    const params = new URLSearchParams(window.location.search);
    const hotelId = params.get("hotel");
    if (params.get("new") === "hotel") {
      setActiveTab("hotels");
      setEditingItem({type:"hotels",data:{name:"",destinationId:request.data.destinations[0]?.id ?? "",
        stayType:"Registered Hotel",pricePerNight:0,lat:"",lng:""}});
      setIsDrawerOpen(true);
    } else if (hotelId) {
      const hotel = request.data.hotels.find(h => h.id === hotelId);
      setActiveTab("hotels");
      if (hotel) { setEditingItem({type:"hotels",id:hotel.id,data:{...hotel}}); setIsDrawerOpen(true); }
      else setRequestError("The requested hotel no longer exists.");
    }
  }, [request.data]);

  const showToast = (msg: string) => {
    setNotice(msg);
    setTimeout(() => {
      setNotice(null);
    }, 3500);
  };

  const handleOpenAddDrawer = () => {
    setFormError(null);
    setEditingItem({type:activeTab,data:{name:"",district:"",category:"Heritage Sites",
      destinationId:destinations[0]?.id ?? "",stayType:"Registered Hotel",pricePerNight:0,
      lat:"",lng:"",visitDurationHours:1,entryFee:"",entryFeeNumeric:null,avgCostPerPerson:0}});
    setIsDrawerOpen(true);
  };

  const handleOpenEditDrawer = (item: any) => {
    setFormError(null);
    setEditingItem({
      type: activeTab,
      id: item.id,
      data: { ...item },
    });
    setIsDrawerOpen(true);
  };

  const handleSaveDrawerItem = async () => {
    if(!editingItem || pending) return;
    const d=editingItem.data;
    if(!d.name?.trim()) { setFormError("Record Name is required."); return; }
    const requiredPrice = editingItem.type === "hotels" ? d.pricePerNight : editingItem.type === "restaurants" ? d.avgCostPerPerson : undefined;
    if ((editingItem.type === "hotels" || editingItem.type === "restaurants") && (requiredPrice == null || String(requiredPrice).trim() === "")) {
      setFormError("Enter a known price. A blank price cannot be saved as zero."); return;
    }
    if(editingItem.type !== "destinations" && (!d.destinationId || d.lat === "" || d.lng === "")) {
      setFormError("Choose a destination and enter verified coordinates."); return;
    }
    const body: Record<string,unknown> = {name:d.name};
    if(editingItem.type === "destinations") {
      Object.assign(body,{district:d.district || null,official_category:d.category});
      if(!editingItem.id) body.slug=d.name.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"") || `destination-${crypto.randomUUID()}`;
    } else {
      Object.assign(body,{destination_id:d.destinationId,lat:Number(d.lat),lng:Number(d.lng)});
      if(editingItem.type === "hotels") Object.assign(body,{stay_type:d.stayType,price_per_night:Number(d.pricePerNight)});
      if(editingItem.type === "attractions") Object.assign(body,{category:d.category,duration_hours:Number(d.visitDurationHours),entry_fee:d.entryFee || null,entry_fee_numeric:d.entryFeeNumeric === "" || d.entryFeeNumeric == null ? null : Number(d.entryFeeNumeric)});
      if(editingItem.type === "restaurants") Object.assign(body,{avg_cost_per_person:Number(d.avgCostPerPerson),location:d.location || null,cuisine:d.cuisine || null});
    }
    setPending(true); setRequestError(""); setFormError(null);
    try {
      await api.adminSave(editingItem.type,editingItem.id,body);
      setIsDrawerOpen(false); request.reload(); showToast("Record saved to the server.");
    } catch(error) { setRequestError(errorMessage(error)); }
    finally { setPending(false); }
  };
  const handleConfirmDelete = async (id: string) => {
    if(pending) return;
    setPending(true); setRequestError("");
    try { await api.adminDelete(activeTab,id); setDeletingId(null); request.reload(); showToast("Record deleted from the server."); }
    catch(error) { setRequestError(errorMessage(error)); }
    finally { setPending(false); }
  };
  if(request.loading || pending) return <p role="status">{pending ? "Saving catalog changes..." : "Loading operator catalog..."}</p>;
  if(request.error || requestError) return <p role="alert">{request.error || requestError} <button onClick={() => {setRequestError(""); request.reload();}}>Retry</button> <button onClick={onBackToProfile}>Back to profile</button></p>;

  return (
    <div className="bg-salt min-h-screen py-8 px-4 sm:px-6 lg:px-8 border-b border-stone/30 animate-fadeIn selection:bg-gold selection:text-ink font-mono text-xs">
      <div className="max-w-7xl mx-auto space-y-8">
        {onBackToProfile && (
          <div className="flex items-center justify-between border-b border-stone/30 pb-4">
            <button
              onClick={onBackToProfile}
              className="inline-flex items-center gap-2 bg-ink text-salt border border-gold hover:bg-ink/90 px-4 py-2 cursor-pointer font-bold transition-colors"
            >
              <ArrowLeft className="w-3.5 h-3.5 text-gold" />
              <span>Back to Profile Console</span>
            </button>
            <span className="text-stone">Tourism Guild Admin (Demo Mode)</span>
          </div>
        )}

        {/* HEADER */}
        <div className="bg-ink text-salt p-6 sm:p-8 border-2 border-gold space-y-4 shadow-lg relative overflow-hidden">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-stone/30 pb-4">
            <div>
              <div className="flex items-center gap-2 text-[11px] uppercase tracking-widest text-gold mb-1">
                <Sparkles className="w-4 h-4 text-gold" />
                <span>ASI & TCGL Dataset Registry</span>
              </div>
              <h1 className="font-display text-2xl sm:text-4xl text-salt font-bold">
                {t("nav.admin", "Admin Content Dashboard")}
              </h1>
            </div>

            <button
              onClick={handleOpenAddDrawer}
              className="bg-madder hover:bg-madder/90 text-salt border border-madder font-bold px-4 py-2.5 flex items-center gap-2 shadow-xs cursor-pointer shrink-0"
            >
              <Plus className="w-4 h-4 text-salt" />
              <span>Add New Record</span>
            </button>
          </div>

          <div className="flex flex-wrap items-center gap-6 text-stone text-[11px]">
            <span>
              Destinations: <strong>{destinations.length}</strong>
            </span>
            <span>•</span>
            <span>
              Hotels: <strong>{hotels.length}</strong>
            </span>
            <span>•</span>
            <span>
              Attractions: <strong>{attractions.length}</strong>
            </span>
            <span>•</span>
            <span>
              Restaurants: <strong>{restaurants.length}</strong>
            </span>
          </div>
        </div>

        {notice && (
          <div className="p-3 bg-emerald-900 text-salt border-2 border-emerald-400 flex items-center gap-2 shadow-md animate-fadeIn">
            <Check className="w-4 h-4 text-emerald-300" />
            <span className="font-bold">{notice}</span>
          </div>
        )}

        {/* TAB CONTROLS */}
        <div className="flex flex-wrap items-center gap-2 border-b-2 border-gold pb-3">
          <button
            onClick={() => setActiveTab("destinations")}
            className={`px-4 py-2 border font-bold transition-colors cursor-pointer flex items-center gap-2 ${
              activeTab === "destinations"
                ? "bg-gold text-ink border-ink"
                : "bg-white text-charcoal border-stone/30 hover:border-gold"
            }`}
          >
            <Compass className="w-4 h-4" />
            <span>Destinations ({destinations.length})</span>
          </button>

          <button
            onClick={() => setActiveTab("hotels")}
            className={`px-4 py-2 border font-bold transition-colors cursor-pointer flex items-center gap-2 ${
              activeTab === "hotels"
                ? "bg-gold text-ink border-ink"
                : "bg-white text-charcoal border-stone/30 hover:border-gold"
            }`}
          >
            <Building2 className="w-4 h-4" />
            <span>Hotels & Stays ({hotels.length})</span>
          </button>

          <button
            onClick={() => setActiveTab("attractions")}
            className={`px-4 py-2 border font-bold transition-colors cursor-pointer flex items-center gap-2 ${
              activeTab === "attractions"
                ? "bg-gold text-ink border-ink"
                : "bg-white text-charcoal border-stone/30 hover:border-gold"
            }`}
          >
            <Layers className="w-4 h-4" />
            <span>Attractions ({attractions.length})</span>
          </button>

          <button
            onClick={() => setActiveTab("restaurants")}
            className={`px-4 py-2 border font-bold transition-colors cursor-pointer flex items-center gap-2 ${
              activeTab === "restaurants"
                ? "bg-gold text-ink border-ink"
                : "bg-white text-charcoal border-stone/30 hover:border-gold"
            }`}
          >
            <Utensils className="w-4 h-4" />
            <span>Restaurants ({restaurants.length})</span>
          </button>
        </div>

        {/* DATA TABLE */}
        <div className="bg-white border-2 border-stone/40 shadow-sm overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-ink text-salt uppercase text-[10px] tracking-wider border-b border-stone/40">
                <th className="p-3 border-r border-stone/30">ID / Name</th>
                <th className="p-3 border-r border-stone/30">
                  District / Location
                </th>
                <th className="p-3 border-r border-stone/30">
                  Category / Type
                </th>
                <th className="p-3 border-r border-stone/30">Metrics</th>
                <th className="p-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-stone/20">
              {activeTab === "destinations" &&
                destinations.map((d) => (
                  <tr key={d.id} className="hover:bg-salt/60 transition-colors">
                    <td className="p-3 border-r border-stone/20 font-bold text-ink">
                      {d.name}{" "}
                      <span className="text-[10px] text-stone font-normal block">
                        {d.id}
                      </span>
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      {d.district}
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      <span className="bg-salt border border-stone/30 px-2 py-0.5 text-[10px] uppercase">
                        {d.category}
                      </span>
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      ₹{d.estimatedCost} • ★ {d.rating}
                    </td>
                    <td className="p-3 text-right space-x-2 whitespace-nowrap">
                      <button
                        onClick={() => handleOpenEditDrawer(d)}
                        className="bg-salt hover:bg-stone/20 text-ink border border-stone/40 px-2.5 py-1 cursor-pointer"
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => setDeletingId(d.id)}
                        className="bg-salt hover:bg-madder/10 text-madder border border-stone/40 px-2.5 py-1 cursor-pointer"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}

              {activeTab === "hotels" &&
                hotels.map((h) => (
                  <tr key={h.id} className="hover:bg-salt/60 transition-colors">
                    <td className="p-3 border-r border-stone/20 font-bold text-ink">
                      {h.name}{" "}
                      <span className="text-[10px] text-stone font-normal block">
                        {h.id}
                      </span>
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      {h.district} ({h.destinationId})
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      <span className="bg-gold/20 text-ink border border-gold px-2 py-0.5 text-[10px] uppercase font-bold">
                        {h.stayType}
                      </span>
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      ₹{h.pricePerNight}/night • ★ {h.rating}
                    </td>
                    <td className="p-3 text-right space-x-2 whitespace-nowrap">
                      <button
                        onClick={() => handleOpenEditDrawer(h)}
                        className="bg-salt hover:bg-stone/20 text-ink border border-stone/40 px-2.5 py-1 cursor-pointer"
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => setDeletingId(h.id)}
                        className="bg-salt hover:bg-madder/10 text-madder border border-stone/40 px-2.5 py-1 cursor-pointer"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}

              {activeTab === "attractions" &&
                attractions.map((a) => (
                  <tr key={a.id} className="hover:bg-salt/60 transition-colors">
                    <td className="p-3 border-r border-stone/20 font-bold text-ink">
                      {a.name}{" "}
                      <span className="text-[10px] text-stone font-normal block">
                        {a.id}
                      </span>
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      {a.destinationName} ({a.district})
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      <span className="bg-salt border border-stone/30 px-2 py-0.5 text-[10px] uppercase">
                        {a.category}
                      </span>
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      {a.entryFee} • {a.visitDurationHours} hrs
                    </td>
                    <td className="p-3 text-right space-x-2 whitespace-nowrap">
                      <button
                        onClick={() => handleOpenEditDrawer(a)}
                        className="bg-salt hover:bg-stone/20 text-ink border border-stone/40 px-2.5 py-1 cursor-pointer"
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => setDeletingId(a.id)}
                        className="bg-salt hover:bg-madder/10 text-madder border border-stone/40 px-2.5 py-1 cursor-pointer"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}

              {activeTab === "restaurants" &&
                restaurants.map((r) => (
                  <tr key={r.id} className="hover:bg-salt/60 transition-colors">
                    <td className="p-3 border-r border-stone/20 font-bold text-ink">
                      {r.name}{" "}
                      <span className="text-[10px] text-stone font-normal block">
                        {r.id}
                      </span>
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      {r.location} ({r.city})
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      <span className="bg-salt border border-stone/30 px-2 py-0.5 text-[10px] uppercase">
                        {r.cuisine}
                      </span>
                    </td>
                    <td className="p-3 border-r border-stone/20">
                      ₹{r.avgCostPerPerson}/head • ★ {r.rating}
                    </td>
                    <td className="p-3 text-right space-x-2 whitespace-nowrap">
                      <button
                        onClick={() => handleOpenEditDrawer(r)}
                        className="bg-salt hover:bg-stone/20 text-ink border border-stone/40 px-2.5 py-1 cursor-pointer"
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => setDeletingId(r.id)}
                        className="bg-salt hover:bg-madder/10 text-madder border border-stone/40 px-2.5 py-1 cursor-pointer"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
            </tbody>
          </table>
        </div>

        {/* DRAWER MODAL */}
        {isDrawerOpen && editingItem && (
          <div className="fixed inset-0 bg-ink/70 backdrop-blur-xs z-50 flex justify-end animate-fadeIn">
            <div className="w-full max-w-md bg-salt h-full border-l-2 border-gold p-6 space-y-6 overflow-y-auto shadow-2xl flex flex-col justify-between">
              <div className="space-y-4">
                <div className="flex items-center justify-between border-b border-stone/30 pb-3">
                  <h3 className="font-display text-lg text-ink font-bold uppercase">
                    {editingItem.id ? "Edit Record" : "Add New Record"} (
                    {editingItem.type})
                  </h3>
                  <button
                    onClick={() => setIsDrawerOpen(false)}
                    className="text-stone hover:text-charcoal cursor-pointer"
                  >
                    <X className="w-5 h-5" />
                  </button>
                </div>

                {formError && (
                  <div className="p-3 bg-madder/10 border-l-4 border-madder text-madder text-xs flex items-center gap-2">
                    <AlertCircle className="w-4 h-4 shrink-0" />
                    <span>{formError}</span>
                  </div>
                )}

                <div className="space-y-3">
                  <div>
                    <label className="block text-[10px] uppercase tracking-wider text-stone mb-1 font-bold">
                      Record Title / Name *
                    </label>
                    <input
                      type="text"
                      value={editingItem.data.name || ""}
                      onChange={(e) =>
                        setEditingItem({
                          ...editingItem,
                          data: { ...editingItem.data, name: e.target.value },
                        })
                      }
                      className="w-full p-2 bg-white border border-stone/40 outline-none focus:border-gold"
                      required
                    />
                  </div>

                  {editingItem.type !== "destinations" && (
                    <>
                      <div>
                        <label className="block text-[10px] uppercase tracking-wider text-stone mb-1 font-bold">Destination *</label>
                        <select value={editingItem.data.destinationId || ""} onChange={e => setEditingItem({...editingItem,data:{...editingItem.data,destinationId:e.target.value}})} className="w-full p-2 bg-white border border-stone/40 outline-none focus:border-gold">
                          <option value="">Select destination</option>
                          {destinations.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                        </select>
                      </div>
                      {(["lat", "lng"] as const).map(field => (
                        <div key={field}>
                          <label className="block text-[10px] uppercase tracking-wider text-stone mb-1 font-bold">{field === "lat" ? "Latitude" : "Longitude"} *</label>
                          <input type="number" step="any" value={editingItem.data[field] ?? ""} onChange={e => setEditingItem({...editingItem,data:{...editingItem.data,[field]:e.target.value}})} className="w-full p-2 bg-white border border-stone/40 outline-none focus:border-gold" required />
                        </div>
                      ))}
                    </>
                  )}
                  {editingItem.type === "attractions" && (
                    <>
                      {(["category", "visitDurationHours", "entryFeeNumeric"] as const).map(field => (
                        <div key={field}>
                          <label className="block text-[10px] uppercase tracking-wider text-stone mb-1 font-bold">{field === "category" ? "Category *" : field === "visitDurationHours" ? "Visit duration (hours) *" : "Entry price (leave blank if unknown)"}</label>
                          <input type={field === "category" ? "text" : "number"} step="any" value={editingItem.data[field] ?? ""} onChange={e => setEditingItem({...editingItem,data:{...editingItem.data,[field]:e.target.value}})} className="w-full p-2 bg-white border border-stone/40 outline-none focus:border-gold" />
                        </div>
                      ))}
                    </>
                  )}
                  {editingItem.type === "restaurants" && (
                    <div>
                      <label className="block text-[10px] uppercase tracking-wider text-stone mb-1 font-bold">Cost per person *</label>
                      <input type="number" value={editingItem.data.avgCostPerPerson ?? ""} onChange={e => setEditingItem({...editingItem,data:{...editingItem.data,avgCostPerPerson:e.target.value}})} className="w-full p-2 bg-white border border-stone/40 outline-none focus:border-gold" required />
                    </div>
                  )}
                  {editingItem.type === "destinations" && (
                    <>
                      <div>
                        <label className="block text-[10px] uppercase tracking-wider text-stone mb-1 font-bold">
                          District
                        </label>
                        <input
                          type="text"
                          value={editingItem.data.district || ""}
                          onChange={(e) =>
                            setEditingItem({
                              ...editingItem,
                              data: {
                                ...editingItem.data,
                                district: e.target.value,
                              },
                            })
                          }
                          className="w-full p-2 bg-white border border-stone/40 outline-none focus:border-gold"
                        />
                      </div>

                      <div>
                        <label className="block text-[10px] uppercase tracking-wider text-stone mb-1 font-bold">
                          Category
                        </label>
                        <select
                          value={
                            editingItem.data.category || CATEGORY_TAXONOMY[0]
                          }
                          onChange={(e) =>
                            setEditingItem({
                              ...editingItem,
                              data: {
                                ...editingItem.data,
                                category: e.target.value,
                              },
                            })
                          }
                          className="w-full p-2 bg-white border border-stone/40 outline-none focus:border-gold"
                        >
                          {CATEGORY_TAXONOMY.map((cat) => (
                            <option key={cat} value={cat}>
                              {cat}
                            </option>
                          ))}
                        </select>
                      </div>
                    </>
                  )}

                  {editingItem.type === "hotels" && (
                    <>
                      <div>
                        <label className="block text-[10px] uppercase tracking-wider text-stone mb-1 font-bold">
                          Stay Type Taxonomy
                        </label>
                        <select
                          value={
                            editingItem.data.stayType || STAY_TYPE_TAXONOMY[0]
                          }
                          onChange={(e) =>
                            setEditingItem({
                              ...editingItem,
                              data: {
                                ...editingItem.data,
                                stayType: e.target.value,
                              },
                            })
                          }
                          className="w-full p-2 bg-white border border-stone/40 outline-none focus:border-gold"
                        >
                          {STAY_TYPE_TAXONOMY.map((st) => (
                            <option key={st} value={st}>
                              {st}
                            </option>
                          ))}
                        </select>
                      </div>

                      <div>
                        <label className="block text-[10px] uppercase tracking-wider text-stone mb-1 font-bold">
                          Price Per Night (₹)
                        </label>
                        <input
                          type="number"
                          value={editingItem.data.pricePerNight ?? ""}
                          onChange={(e) =>
                            setEditingItem({
                              ...editingItem,
                              data: {
                                ...editingItem.data,
                                pricePerNight: e.target.value,
                              },
                            })
                          }
                          className="w-full p-2 bg-white border border-stone/40 outline-none focus:border-gold"
                        />
                      </div>
                    </>
                  )}
                </div>
              </div>

              <div className="pt-4 border-t border-stone/30 flex items-center justify-end gap-2">
                <button
                  onClick={() => setIsDrawerOpen(false)}
                  className="px-4 py-2 bg-salt border border-stone/40 text-charcoal hover:bg-stone/20 cursor-pointer"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSaveDrawerItem}
                  className="px-4 py-2 bg-gold text-ink font-bold border border-ink hover:bg-gold/90 cursor-pointer"
                >
                  Save Record
                </button>
              </div>
            </div>
          </div>
        )}

        {/* DELETE CONFIRMATION DIALOG */}
        {deletingId && (
          <div className="fixed inset-0 bg-ink/70 backdrop-blur-xs z-50 flex items-center justify-center p-4 animate-fadeIn">
            <div className="bg-salt border-2 border-madder p-6 max-w-sm w-full space-y-4 shadow-2xl">
              <h4 className="font-display text-lg text-madder font-bold flex items-center gap-2">
                <AlertCircle className="w-5 h-5 text-madder" />
                <span>Confirm Record Deletion</span>
              </h4>
              <p className="text-stone leading-relaxed">
                Are you sure you want to delete this entry from the dataset?
                This action cannot be undone.
              </p>
              <div className="flex items-center justify-end gap-2 pt-2">
                <button
                  onClick={() => setDeletingId(null)}
                  className="px-3 py-1.5 bg-salt border border-stone/40 text-charcoal cursor-pointer"
                >
                  Cancel
                </button>
                <button
                  onClick={() => handleConfirmDelete(deletingId)}
                  className="px-3 py-1.5 bg-madder text-salt font-bold border border-madder cursor-pointer"
                >
                  Delete Record
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

frontend/src/components/AccessibilityBad:
import React from "react";
import { Accessibility } from "lucide-react";

interface AccessibilityBadgeProps {
  wheelchairAccessible?: boolean;
  physicalDemand?: "low" | "moderate" | "high";
  compact?: boolean;
}

export const AccessibilityBadge: React.FC<AccessibilityBadgeProps> = ({
  wheelchairAccessible,
  physicalDemand,
  compact = false,
}) => {
  if (wheelchairAccessible === undefined && !physicalDemand) return null;

  const filledSteps =
    physicalDemand === "low" ? 1 : physicalDemand === "moderate" ? 2 : 3;

  const demandStyles =
    physicalDemand === "low"
      ? "text-emerald-800 bg-emerald-50 border-emerald-300"
      : physicalDemand === "moderate"
        ? "text-amber-800 bg-amber-50 border-amber-300"
        : "text-madder bg-red-50 border-red-300";

  return (
    <div className="flex flex-wrap items-center gap-1.5 font-mono text-[10px] uppercase font-bold">
      {wheelchairAccessible !== undefined && (
        <span
          className={`inline-flex items-center gap-1 px-2 py-0.5 border ${
            wheelchairAccessible
              ? "bg-emerald-100/90 text-emerald-950 border-emerald-400"
              : "bg-stone/10 text-stone border-stone/30"
          }`}
          title={
            wheelchairAccessible
              ? "Wheelchair accessible"
              : "Not wheelchair accessible"
          }
        >
          <Accessibility
            className={`w-3.5 h-3.5 ${
              wheelchairAccessible
                ? "text-emerald-700 font-bold"
                : "text-stone/60"
            }`}
          />
          {!compact && (
            <span>
              {wheelchairAccessible
                ? "Wheelchair Accessible"
                : "Not Wheelchair Accessible"}
            </span>
          )}
        </span>
      )}

      {physicalDemand && (
        <span
          className={`inline-flex items-center gap-1.5 px-2 py-0.5 border ${demandStyles}`}
        >
          <div
            className="inline-flex items-end gap-0.5 h-3 shrink-0"
            aria-label={`Physical demand level: ${physicalDemand}`}
            title={`Physical Demand: ${physicalDemand}`}
          >
            <span
              className={`w-1 rounded-2xs ${
                filledSteps >= 1 ? "h-1.5 bg-current" : "h-1.5 bg-stone/30"
              }`}
            />
            <span
              className={`w-1 rounded-2xs ${
                filledSteps >= 2 ? "h-2.5 bg-current" : "h-2.5 bg-stone/30"
              }`}
            />
            <span
              className={`w-1 rounded-2xs ${
                filledSteps >= 3 ? "h-3.5 bg-current" : "h-3.5 bg-stone/30"
              }`}
            />
          </div>
          <span>{physicalDemand} Demand</span>
        </span>
      )}
    </div>
  );
};
